type DesignSettings = { sections: { add: string[]; hide: string[] }; names: Record<string, string>; pieces: { add: string[]; hide: string[] }; [key: string]: any };
const parseDesign = (raw: any): DesignSettings => {
  try {
    const j = JSON.parse(String(raw || ""));
    if (j && typeof j === "object" && !Array.isArray(j)) {
      return {
        ...j,
        sections: {
          add: Array.isArray(j.sections?.add) ? j.sections.add.map(String) : [],
          hide: Array.isArray(j.sections?.hide) ? j.sections.hide.map(String) : [],
        },
        names: j.names && typeof j.names === "object" && !Array.isArray(j.names) ? j.names : {},
        pieces: {
          add: Array.isArray(j.pieces?.add) ? j.pieces.add.map(String) : [],
          hide: Array.isArray(j.pieces?.hide) ? j.pieces.hide.map(String) : [],
        },
      };
    }
  } catch { /* an empty or broken box reads as no choices */ }
  return { sections: { add: [], hide: [] }, names: {}, pieces: { add: [], hide: [] } };
};
