// Where a write leaves a card, by the Scripting Studio's own rule
// (scripting-studio-v1.tsx stageForWrite). "" means the write does not move
// the stage: a discard is a verdict, not a move.
function stageForMove(fields: any, isGraphic: boolean): string {
  const has = (k: string) => Object.prototype.hasOwnProperty.call(fields || {}, k);
  const lab = (k: string) => (has(k) ? selectLabel(fields[k]) || String(fields[k] ?? "") : undefined);
  const ph = lab("status"), sh = lab("shootingStatus"), pp = lab("postProductionStatus");
  const edit = isGraphic ? "To Design" : "To Edit";
  if (pp === "Discard") return "";
  if (ph === "Ready to Post" || pp === "Ready to Post") return "To Schedule";
  if (pp === "In Progress") return "In Progress";
  if (pp === "To Approve") return "Approve Media";
  if (pp === "To Design") return "To Design";
  if (pp === "New Shots" || pp === "Creatives Queue" || pp === "Flowy's Queue"
    || sh === "Sent to Post Production" || ph === "Post Production") return edit;
  if (sh === "To Shoot" || ph === "Shoot Plan") return "Shoot";
  if (ph === "Scripting") return "Review Script";
  return "";
}
