// The brand's people, read once per brand and kept for the session. Used to
// sign a comment and to fill the assignee lists on the board and in the
// record window.
const membersCache: Record<string, any[]> = {};
async function loadBrandMembers(brandId: string): Promise<any[]> {
  if (!brandId) return [];
  if (membersCache[brandId]) return membersCache[brandId];
  try {
    const r = await fetch(BRAND_MEMBERS_WEBHOOK, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ brandId }) });
    const j = await r.json().catch(() => null);
    const ms = (Array.isArray(j) && j) || (j && j.members) || (j && j.data) || [];
    const normalized = (ms as any[]).map((m: any) => {
      const raw = m?.fields || m;
      return { id: m?.id || raw?.id || null, displayName: raw?.displayName || raw?.["Display Name"] || raw?.name || raw?.email || "Member", email: raw?.email || raw?.Email || "", role: raw?.role || raw?.Role || "" };
    });
    membersCache[brandId] = normalized;
    return normalized;
  } catch { return []; }
}

