// ─── Helpers lifted from the studio ──────────────────────────────────────────
// The same, but the writer's starred word stays as *word* (a **word** too),
// for the templates that lift it (2026-10-19).
function stripKeepStar(value: any): string {
  const marked = String(value || "").replace(/\*\*([^*]+)\*\*/g, "\u0001$1\u0001").replace(/\*([^*\s][^*]*)\*/g, "\u0001$1\u0001");
  return stripRichText(marked).replace(/\u0001/g, "*");
}
function stripRichText(value: any): string {
  if (!value) return "";
  let text = String(value);
  text = text.replace(/<[^>]*>/g, "");
  text = text.replace(/\*\*(.*?)\*\*/g, "$1");
  text = text.replace(/\*(.*?)\*/g, "$1");
  text = text.replace(/_(.*?)_/g, "$1");
  text = text.replace(/^#+\s/gm, "");
  text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, "$1");
  text = text.replace(/`/g, "");
  text = text
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, " ");
  return text;
}

// The visual hook's own reading. It marks the word the design makes stand out
// with *stars*, and stripRichText takes stars for formatting and wipes them,
// so a saved emphasis vanished the next time the card loaded (Karen,
// 2026-10-10). Everything else is cleaned the same way; a bolded word comes
// back as the one star word.
function hookText(value: any): string {
  if (!value) return "";
  const kept = String(value).replace(/\*\*(.+?)\*\*/g, "\u0001$1\u0002").replace(/\*([^*\s][^*]*?)\*/g, "\u0001$1\u0002");
  return stripRichText(kept).replace(/\u0001/g, "*").replace(/\u0002/g, "*");
}

function formatDuration(value: any): string {
  if (value === null || value === undefined || value === "") return "";
  const num = typeof value === "number" ? value : parseFloat(String(value));
  if (isNaN(num) || num <= 0) return "";
  if (num < 60) return `${Math.round(num)}s`;
  const mins = Math.floor(num / 60);
  const secs = Math.round(num % 60);
  return secs === 0 ? `${mins}m` : `${mins}m ${secs}s`;
}

function formatRelativeDate(value: any): string {
  if (!value) return "";
  try {
    const d = new Date(value);
    const now = new Date();
    const diffMs = now.getTime() - d.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    if (diffMs < 0) return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
    if (diffMins < 5) return "Now";
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 12) return `${diffHours}h ago`;
    if (diffDays === 0) return "Today";
    if (diffDays === 1) return "Yesterday";
    if (diffDays < 7) return `${diffDays}d ago`;
    if (diffDays < 30) return `${Math.floor(diffDays / 7)}w ago`;
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
  } catch { return ""; }
}

// Airtable formulas, counts and rollups arrive as STRINGS through the
// datasource ("3", not 3). Never strict-check them.
function toNum(v: any): number {
  if (typeof v === "number") return isFinite(v) ? v : 0;
  if (typeof v === "string") { const n = parseFloat(v); return isFinite(n) ? n : 0; }
  if (Array.isArray(v)) return toNum(v[0]);
  return 0;
}

// Shoot-batch labels as the design writes them: "Tue Aug 11" (no comma) and
// a 24-hour start, "10:30" / "14:00", shown after a middle dot.
function formatSessionDay(start: any): string {
  if (!start) return "Unscheduled";
  const d = new Date(start);
  if (isNaN(d.getTime())) return "Unscheduled";
  const weekday = d.toLocaleDateString("en-US", { weekday: "short" });
  const month = d.toLocaleDateString("en-US", { month: "short" });
  return `${weekday} ${month} ${d.getDate()}`;
}
function formatSessionTime(start: any): string {
  if (!start) return "";
  const d = new Date(start);
  if (isNaN(d.getTime())) return "";
  return `${d.getHours()}:${String(d.getMinutes()).padStart(2, "0")}`;
}

// Walks every page of a datasource read. `count` is capped at 100 per page.
function useAllPages(read: any) {
  const hasNext = !!read?.hasNextPage;
  const busy = !!read?.isFetchingNextPage || !!read?.isFetching;
  const pages = read?.data?.pages?.length || 0;
  useEffect(() => {
    if (hasNext && !busy && typeof read?.fetchNextPage === "function") {
      try { read.fetchNextPage(); } catch { /* the next render tries again */ }
    }
  }, [hasNext, busy, pages]);
}

const stubToast = (message: string = NEXT_ROUND) => {
  // Green, the colour of a thing done, as on the Scheduling Board (Karen,
  // 2026-10-07/08). Errors stay red.
  const id = toast(message, { style: { background: "#15803D", color: "white", border: "none" }, duration: 2000 });
  setTimeout(() => toast.dismiss(id), 2200);
  return id;
};

// The bytes an upload has sent so far (Karen, 2026-10-17: the bar moved back
// and forth and said nothing about how far a file had got). Softr's
// useUpload reports only done or failed, so while a file goes out this
// listens to the browser's own upload progress on any large request it
// makes. If Softr sends with fetch instead, nothing is heard and the bar
// moves by whole files. Watching never touches the upload itself.
function watchUploadBytes(onSent: (sent: number) => void): () => void {
  const XHR: any = typeof window !== "undefined" ? (window as any).XMLHttpRequest : null;
  if (!XHR || !XHR.prototype || typeof XHR.prototype.send !== "function") return () => {};
  const proto = XHR.prototype;
  const send = proto.send;
  proto.send = function (this: any, body?: any) {
    try {
      let size = body && typeof body.size === "number" ? body.size : body && typeof body.byteLength === "number" ? body.byteLength : 0;
      if (!size && typeof FormData !== "undefined" && body instanceof FormData) {
        body.forEach((v: any) => { if (v && typeof v.size === "number") size += v.size; });
      }
      if (size > 100000 && this.upload && typeof this.upload.addEventListener === "function") {
        this.upload.addEventListener("progress", (e: any) => { if (e && typeof e.loaded === "number") onSent(e.loaded); });
      }
    } catch { /* never in the upload's way */ }
    return send.apply(this, arguments as any);
  };
  return () => { proto.send = send; };
}
// Megabytes for the upload strip: one decimal under 10 MB, whole above.
const mbOf = (bytes: number) => {
  const mb = bytes / 1048576;
  return mb < 10 ? `${mb.toFixed(1)} MB` : `${Math.round(mb)} MB`;
};

// The id of a record Softr just created, in each shape the answer comes in
// (scripting-studio-v1.tsx newRecordId).
function newRecordId(data: any): string | null {
  return data?.record?.id || data?.id || data?.records?.[0]?.id || null;
}

// A linked record arrives as EITHER a one-item array or a bare object. Always
// go through this.
function firstLink(v: any): { id: string; label: string } | null {
  const x = Array.isArray(v) ? v[0] : v;
  if (!x || typeof x !== "object") return null;
  return { id: String(x.id || ""), label: String(x.label || x.name || "") };
}
function allLinks(v: any): { id: string; label: string }[] {
  const arr = Array.isArray(v) ? v : (v ? [v] : []);
  return arr
    .filter((x: any) => x && typeof x === "object")
    .map((x: any) => ({ id: String(x.id || ""), label: String(x.label || x.name || "") }));
}
function selectLabel(v: any): string {
  if (!v) return "";
  if (typeof v === "string") return v;
  if (Array.isArray(v)) return selectLabel(v[0]);
  return String(v.label || v.name || "");
}
