const tplCtaPill = (t: string, align = "flex-start") => (t ? `<span style="align-self:${align};max-width:100%;box-sizing:border-box;padding:8px 15px;line-height:1.3;border-radius:9px;background:var(--pillBg, var(--highlight));color:var(--pillInk, var(--text-on-highlight));font-family:var(--fContrast);font-size:11px;font-weight:600;letter-spacing:.01em;display:inline-flex;align-items:center">${tplEsc(t)}</span>` : "");
const TPL_PILL_H = 30;
// ── Organic words (round 151, Karen 2026-10-20) ──
// The way people type on a post in Instagram or TikTok: one plain face
// (Inter, close to theirs), small (about 40 to 50px on a 1080 slide, from
// Karen's examples), none of a design's marks. Plain: white words with a soft
// shadow (the kit's text colour on a light background). White Backing: each
// line in a white rounded box. Glass: each line in a frosted box.
const TPL_ORGANIC: Record<string, number[]> = { s: [13, 11.5], m: [15, 13], l: [17.5, 15] };
// The lines words break into, for boxes that hug each line.
const tplBreak = (t: string, f: TplFont, w: number, size: number) => {
  const k = size / 100, sp = tplW100(" ", f) * k, out: string[] = [];
  String(t).split("\n").forEach((para) => {
    let cur = "", cw = 0;
    para.split(/\s+/).filter(Boolean).forEach((x) => {
      const ww = tplW100(x, f) * k;
      if (cur && cw + sp + ww > w) { out.push(cur); cur = x; cw = ww; return; }
      cw = cur ? cw + sp + ww : ww;
      cur = cur ? cur + " " + x : x;
    });
    if (cur) out.push(cur);
  });
  return out;
};
const tplOrganic = (sl: TplSlide, pick: TplPick, C: TplCtx, o: { align?: "left" | "center"; number?: string; box?: { left: number; right: number; top: number; bottom: number }; photo?: boolean; judged?: string; inkHex?: string; end?: boolean } = {}) => {
  const B = o.box || { left: C.wl, right: C.right, top: C.top, bottom: C.H - C.bottom };
  // On a photo the words are white with a soft shadow; on a colour, white or
  // black, whichever stands out there (Karen, 2026-10-20: "in organic we can
  // play white/black depending on ground").
  const judged = o.judged || C.judged;
  const onPhoto = !!(o.photo || C.photo);
  const dark = onPhoto ? true : judged ? tplContrast("#FFFFFF", judged) >= tplContrast("#000000", judged) : C.dark;
  const align = o.align || "left";
  const w = C.W - B.left - B.right, room = C.H - B.top - B.bottom;
  const plainOf = (t: string) => String(t || "").replace(/\*/g, "").trim();
  const bigText = (o.number ? o.number + " " : "") + plainOf(sl.big);
  const parts = [sl.label ? { t: plainOf(sl.label), big: false } : null, bigText ? { t: bigText, big: true } : null, sl.small ? { t: plainOf(sl.small), big: false } : null, sl.cta ? { t: plainOf(sl.cta) + " \u2192", big: false } : null].filter(Boolean) as { t: string; big: boolean }[];
  const BF: TplFont = { fam: "'Inter',sans-serif", w: "600" }, SF: TplFont = { fam: "'Inter',sans-serif", w: C.style === "plain" ? "500" : "600" };
  const boxed = C.style !== "plain";
  // The style's sizes, stepped down together when the words need more room.
  let [bs, ss] = TPL_ORGANIC[C.size] || TPL_ORGANIC.s;
  const pad = boxed ? 0.9 : 0;
  const heightAt = (k: number) => parts.reduce((h, x) => {
    const size = (x.big ? bs : ss) * k;
    const n = boxed ? tplBreak(x.t, x.big ? BF : SF, w - size * pad, size).length : Math.max(1, tplLinesAt(x.t, x.big ? BF : SF, w * 0.97, size) || 2);
    return h + n * size * (boxed ? 1.62 : 1.36) + 10;
  }, 0);
  let k = 1;
  while (k > 0.78 && heightAt(k) > room) k -= 0.04;
  // Every slide of the same kind steps down together.
  k = tplPlanned(C, `org.${sl.key === "cover" || sl.key === "closing" ? sl.key : "slide"}${o.box ? (o.photo ? ".photo" : ".half") : ""}`, k);
  bs *= k; ss *= k;
  const color = dark ? "#FFFFFF" : "#000000";
  const shadow = dark ? `text-shadow:0 1px 3px rgba(0,0,0,${onPhoto ? ".42" : ".3"}),0 2px 14px rgba(0,0,0,${onPhoto ? ".38" : ".25"});` : "";
  // Glass on a photo is smoked, so white words read on its light parts too.
  const boxCss = C.style === "glass"
    ? (onPhoto ? "background:rgba(18,18,18,.34);color:#FFFFFF;box-shadow:inset 0 0 0 1px rgba(255,255,255,.18);" : dark ? "background:rgba(255,255,255,.17);color:#FFFFFF;box-shadow:inset 0 0 0 1px rgba(255,255,255,.3);" : "background:rgba(255,255,255,.58);color:#111111;box-shadow:inset 0 0 0 1px rgba(0,0,0,.06);") + "-webkit-backdrop-filter:blur(12px) saturate(140%);backdrop-filter:blur(12px) saturate(140%);"
    : "background:#FFFFFF;color:#000000;";
  const block = (x: { t: string; big: boolean }) => {
    const size = +(x.big ? bs : ss).toFixed(2), f = x.big ? BF : SF;
    if (!boxed) return `<span style="font-family:'Inter',sans-serif;font-weight:${f.w};font-size:${size}px;line-height:1.36;letter-spacing:-.003em;color:${color};${shadow}text-align:${align}">${tplEsc(x.t)}</span>`;
    const lines = tplBreak(x.t, f, w - size * pad, size);
    return `<div style="display:flex;flex-direction:column;align-items:${align === "center" ? "center" : "flex-start"};gap:${C.style === "glass" ? 3 : 0}px">${lines.map((l) => `<span style="display:inline-block;${boxCss}font-family:'Inter',sans-serif;font-weight:${f.w};font-size:${size}px;line-height:1.3;letter-spacing:-.004em;padding:${(size * 0.16).toFixed(2)}px ${(size * 0.45).toFixed(2)}px;border-radius:${(size * 0.32).toFixed(2)}px;white-space:nowrap">${tplEsc(l)}</span>`).join("")}</div>`;
  };
  return `<div style="position:absolute;left:${B.left}px;right:${B.right}px;top:${B.top}px;bottom:${B.bottom}px;display:flex;flex-direction:column;justify-content:${o.end ? "flex-end" : "center"};align-items:${align === "center" ? "center" : "flex-start"};gap:10px;text-align:${align}">${parts.map(block).join("")}</div>`;
};
// A cover or a closing, and the words of most slides: an accent mark, the
// title, the line under it and the button, sized to the room between the
// marks. `quote` puts the opening mark first; `end` sits the words low.
const tplHeadline = (sl: TplSlide, pick: TplPick, C: TplCtx, o: { mark?: "line" | "quote" | ""; kind: string; weight?: string; end?: boolean; italicLift?: boolean; align?: "left" | "center"; part?: string }) => {
  if (C.organic) return tplOrganic(sl, pick, C, { align: o.align || "left", end: o.end });
  const ink = tplInk(pick.ground), acc = tplAccent(pick.ground);
  const w = C.W - C.wl - C.right, room = C.bottom - C.top, gap = 14;
  const markH = o.mark === "quote" ? 20 : o.mark === "line" ? 1 : 0;
  const labH = sl.label ? 11 : 0;
  const ctaH = sl.cta ? TPL_PILL_H : 0;
  const parts = [markH, labH, 1, sl.small ? 1 : 0, ctaH].filter(Boolean).length;
  const sm = sl.small ? tplFitBox(sl.small, C.body, w, Math.min(room * 0.3, 104), Math.max(10.5, TPL_BODY * C.scale), 10.5, 1.5) : null;
  const tf = { ...C.title, w: o.weight || C.title.w };
  const fit = tplFitBox(sl.big, tf, w, room - markH - labH - ctaH - (sm ? sm.h : 0) - gap * (parts - 1), tplSize(sl.big, o.kind) * C.scale, 13, 1.12);
  const part = o.part || `head.${o.kind}`;
  const tt = { ...fit, size: tplPlanned(C, part, fit.size) };
  const small = sm ? tplPlanned(C, `${part}.small`, Math.max(10.5, Math.min(sm.size, Math.round(tt.size * 0.62 * 2) / 2))) : 0;
  const lift = o.italicLift === false ? tplLift(pick.ground, acc) : `font-style:italic;${tplLiftCss(pick.ground)}`;
  return `<div style="position:absolute;left:${C.wl}px;right:${C.right}px;top:${C.top}px;bottom:${C.H - C.bottom}px;display:flex;flex-direction:column;justify-content:${o.end ? "flex-end" : "center"};gap:${gap}px">`
    + (o.mark === "quote" ? `<svg width="27" height="${markH}" viewBox="0 0 27 20" style="flex-shrink:0;display:block" aria-hidden="true"><path fill="${acc}" d="M5.6 20C2.4 20 0 17.6 0 14.2 0 8.4 3.9 3 10.4 0l1.3 1.9C7.9 4.4 6 7.2 5.7 9.6c.3-.1.6-.1 1-.1 3 0 5.3 2.2 5.3 5.2S9.4 20 5.6 20zm15 0c-3.2 0-5.6-2.4-5.6-5.8 0-5.8 3.9-11.2 10.4-14.2l1.3 1.9c-3.8 2.5-5.7 5.3-6 7.7.3-.1.6-.1 1-.1 3 0 5.3 2.2 5.3 5.2S24.4 20 20.6 20z"></path></svg>` : o.mark === "line" ? `<span style="width:24px;height:1.2px;flex-shrink:0;background:${acc}"></span>` : "")
    + tplEyebrow(sl.label, ink)
    + (sl.big ? `<span style="font-family:var(--fTitle);font-weight:${o.weight || "var(--wTitle)"};font-size:${tt.size}px;line-height:1.12;letter-spacing:-.01em;color:${ink}">${tplWords(sl.big, lift)}</span>` : "")
    + (sl.small ? `<span style="font-family:var(--fBody);font-weight:400;font-size:${small}px;line-height:1.5;color:${ink}">${tplWords(sl.small, tplLift(pick.ground, acc))}</span>` : "")
    + tplCtaPill(sl.cta)
    + `</div>`;
};
// Quote. Dramatic: the opening mark and a big line. Minimal: a quiet
// centred line under a hairline, the brand at the foot.
const tplQuote = (sl: TplSlide, pick: TplPick, C: TplCtx) => {
  const ink = tplInk(pick.ground), acc = tplAccent(pick.ground);
  const bg = `<div style="position:absolute;inset:0;background:${tplBg(pick.ground)}"></div>`;
  const ends = sl.key === "cover" || sl.key === "closing";
  if (C.organic) return bg + tplOrganic(sl, pick, C, { align: pick.look === "minimal" ? "center" : "left" }) + tplMarkFoot(C, ink, pick.look === "minimal");
  if (pick.look === "minimal") {
    const inset = Math.max(C.side + 12, C.right), li = Math.max(inset, C.wl), ri = C.wl > C.side ? C.right : inset;
    const w = C.W - li - ri, room = C.bottom - C.top;
    const part = `quote.${ends ? sl.key : "slide"}`;
    const sm0 = sl.small ? tplFitBox(sl.small, C.body, w, Math.min(room * 0.3, 90), Math.max(10.5, 11 * C.scale), 10, 1.6) : null;
    const sm = sm0 ? { ...sm0, size: tplPlanned(C, part + ".small", sm0.size) } : null;
    const tf = { ...C.title, w: "400" };
    const tt0 = tplFitBox(sl.big, tf, w, room - 30 - (sl.label ? 24 : 0) - (sm0 ? sm0.h + 14 : 0) - (sl.cta ? TPL_PILL_H + 14 : 0), (tplSize(sl.big, "minimal") + (ends ? 2.5 : 0)) * C.scale, 12, 1.38);
    const tt = { ...tt0, size: tplPlanned(C, part, tt0.size) };
    return bg
      + `<div style="position:absolute;left:${li}px;right:${ri}px;top:${C.top}px;bottom:${C.H - C.bottom}px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:14px;text-align:center">`
      + `<span style="width:18px;height:1.2px;flex-shrink:0;background:${acc}"></span>`
      + tplEyebrow(sl.label, ink)
      + (sl.big ? `<span style="font-family:var(--fTitle);font-weight:400;font-size:${tt.size}px;line-height:1.38;color:${ink}">${tplWords(sl.big, `font-style:italic;${tplLiftCss(pick.ground)}`)}</span>` : "")
      + (sl.small ? `<span style="font-family:var(--fBody);font-weight:400;font-size:${sm!.size}px;line-height:1.6;color:${ink}">${tplWords(sl.small, tplLift(pick.ground, acc))}</span>` : "")
      + tplCtaPill(sl.cta, "center")
      + `</div>${tplMarkFoot(C, ink, true)}${tplSwipe(C, ink)}`;
  }
  return bg + tplHeadline(sl, pick, C, { mark: "quote", kind: sl.key === "cover" ? "cover" : sl.key === "closing" ? "closing" : "slide" }) + tplMarkFoot(C, ink) + tplSwipe(C, ink);
};
// The phone's own face for the Notes and Tweet templates. Inter first, so
// the Studio's preview and the rendered picture (drawn on a server that has
// no Apple fonts) use the same face.
const TPL_SYS = "'Inter',-apple-system,BlinkMacSystemFont,'SF Pro Text','Helvetica Neue',Helvetica,sans-serif";
const TPL_SYS_FONT: TplFont = { fam: "'Inter',sans-serif", w: "400" };
// List: one numbered point per slide. Dramatic: a big number in the accent
// with its point under it. Minimal: a small number in a ring over a centred
// point (Karen's limits: the number only a little more prominent than the
// words in minimal, prominent but never hugely bigger in dramatic).
const tplList = (sl: TplSlide, pick: TplPick, C: TplCtx) => {
  const ink = tplInk(pick.ground), acc = tplAccent(pick.ground);
  const em = tplLift(pick.ground, acc);
  const head = `<div style="position:absolute;inset:0;background:${tplBg(pick.ground)}"></div>${tplMarkTop(C, ink)}${tplCount(C, ink)}`;
  const isItem = /^s\d+$/.test(sl.key);
  const num = tplPad2(Math.max(1, Number(sl.key.replace(/\D/g, "")) || C.i));
  if (!isItem) return head + tplHeadline(sl, pick, C, { mark: "line", kind: sl.key === "cover" ? "cover" : "closing", weight: "700", italicLift: false, align: pick.look === "minimal" ? "center" : "left" }) + tplSwipe(C, ink);
  if (C.organic) return head + tplOrganic(sl, pick, C, { align: pick.look === "minimal" ? "center" : "left", number: `${Number(num)}.` });
  const room = C.bottom - C.top;
  if (pick.look === "minimal") {
    const inset = Math.max(C.side + 16, C.right), li = Math.max(inset, C.wl), ri = C.wl > C.side ? C.right : inset, w = C.W - li - ri;
    const sm0 = sl.small ? tplFitBox(sl.small, C.body, w, Math.min(room * 0.32, 96), Math.max(10.5, 11 * C.scale), 10.5, 1.55) : null;
    const sm = sm0 ? { ...sm0, size: tplPlanned(C, "item.small", sm0.size) } : null;
    const tt0 = tplFitBox(sl.big, { ...C.title, w: "600" }, w, room - 34 - 14 - (sm0 ? sm0.h + 14 : 0), Math.min(18, tplSize(sl.big, "minimal") + 1) * C.scale, 12, 1.25);
    const tt = { ...tt0, size: tplPlanned(C, "item", tt0.size) };
    return head + `<div style="position:absolute;left:${li}px;right:${ri}px;top:${C.top}px;bottom:${C.H - C.bottom}px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:14px;text-align:center">`
      + `<span style="width:30px;height:30px;flex-shrink:0;box-sizing:border-box;border-radius:50%;border:1.3px solid ${acc};display:flex;align-items:center;justify-content:center;font-family:var(--fContrast);font-size:10.5px;font-weight:600;letter-spacing:.02em;color:${ink}">${num}</span>`
      + `<span style="font-family:var(--fTitle);font-weight:600;font-size:${tt.size}px;line-height:1.25;color:${ink}">${tplWords(sl.big, em)}</span>`
      + (sl.small ? `<span style="font-family:var(--fBody);font-size:${sm!.size}px;line-height:1.55;color:${ink}">${tplWords(sl.small, em)}</span>` : "")
      + `</div>${tplSwipe(C, ink)}`;
  }
  const w = C.W - C.wl - C.right;
  const sm0 = sl.small ? tplFitBox(sl.small, C.body, w, Math.min(room * 0.3, 100), Math.max(10.5, TPL_BODY * C.scale), 10.5, 1.5) : null;
  const sm = sm0 ? { ...sm0, size: tplPlanned(C, "item.small", sm0.size) } : null;
  const numGuess = 44 * C.scale;
  const tt0 = tplFitBox(sl.big, { ...C.title, w: "700" }, w, room - numGuess * 0.86 - 14 - 1 - 14 - (sm0 ? sm0.h + 14 : 0), tplSize(sl.big, "slide") * C.scale, 13, 1.14);
  const tt = { ...tt0, size: tplPlanned(C, "item", tt0.size) };
  const numSize = Math.max(28, Math.min(numGuess, Math.round(tt.size * 1.9)));
  return head + `<div style="position:absolute;left:${C.wl}px;right:${C.right}px;top:${C.top}px;bottom:${C.H - C.bottom}px;display:flex;flex-direction:column;justify-content:center;gap:14px">`
    + `<span style="font-family:var(--fTitle);font-weight:700;font-size:${numSize}px;line-height:.86;letter-spacing:-.04em;color:${acc}">${num}</span>`
    + `<span style="height:1px;flex-shrink:0;background:${ink};opacity:.18"></span>`
    + `<span style="font-family:var(--fTitle);font-weight:700;font-size:${tt.size}px;line-height:1.14;letter-spacing:-.015em;color:${ink}">${tplWords(sl.big, em)}</span>`
    + (sl.small ? `<span style="font-family:var(--fBody);font-size:${sm!.size}px;line-height:1.5;color:${ink}">${tplWords(sl.small, em)}</span>` : "")
    + `</div>${tplSwipe(C, ink)}`;
};
const TPL_BADGE = '<svg width="12" height="12" viewBox="0 0 24 24" aria-hidden="true"><path fill="#1D9BF0" d="M22.25 12c0-1.43-.88-2.67-2.19-3.34.46-1.39.2-2.9-.81-3.91s-2.52-1.27-3.91-.81c-.66-1.31-1.91-2.19-3.34-2.19s-2.67.88-3.33 2.19c-1.4-.46-2.91-.2-3.92.81s-1.26 2.52-.8 3.91C2.63 9.33 1.75 10.57 1.75 12s.88 2.67 2.2 3.34c-.46 1.39-.21 2.9.8 3.91s2.52 1.26 3.91.81c.67 1.31 1.91 2.19 3.34 2.19s2.68-.88 3.34-2.19c1.39.45 2.9.2 3.91-.81s1.27-2.52.81-3.91c1.31-.67 2.19-1.91 2.19-3.34z"></path><path fill="#FFFFFF" d="M10.54 16.2l-3.6-3.6 1.41-1.42 2.19 2.19 4.86-4.86 1.41 1.42z"></path></svg>';
const tplIcon = (d: string) => `<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#8B9198" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
const TPL_TWEET_ICONS = [
  '<path d="M4 11.5c0-4 3.4-6.5 7.6-6.5h.8C16.6 5 20 7.7 20 11.6c0 3.9-3.2 6.4-7.4 6.4H11l-4.6 3v-3.6C5 16.1 4 14 4 11.5z"></path>',
  '<path d="M4 8.5 7 5.5l3 3M7 5.5v9a3 3 0 0 0 3 3h4.5M20 15.5l-3 3-3-3M17 18.5v-9a3 3 0 0 0-3-3H9.5"></path>',
  '<path d="M12 20s-7.5-4.4-7.5-10A4.3 4.3 0 0 1 12 7.4 4.3 4.3 0 0 1 19.5 10c0 5.6-7.5 10-7.5 10z"></path>',
  '<path d="M6.5 4.5h11v15.5L12 16.3 6.5 20z"></path>',
].map(tplIcon).join("");
// Tweet: every slide a post from the brand, always white and verified, on
// the background picked, at the size a tweet screenshot has in a feed.
const tplTweet = (sl: TplSlide, pick: TplPick, C: TplCtx) => {
  const raw = [sl.big, sl.small].filter(Boolean).map((t) => String(t).replace(/\*/g, "")).join("\n\n");
  const text = tplEsc(raw).replace(/\n/g, "<br>");
  // The brand's own account name when one is connected (Karen, 2026-10-19).
  const own = String(C.account || "").trim().replace(/^@+/, "").replace(/\s+/g, "");
  const handle = "@" + (own || String(C.brand || "brand").toLowerCase().replace(/[^a-z0-9_]+/g, ""));
  const initial = tplEsc((String(C.brand || "B").trim()[0] || "B").toUpperCase());
  const left = C.side, right = C.right, pad = 15;
  const cw = C.W - left - right;
  const fit0 = tplFitBox(raw, TPL_SYS_FONT, cw - pad * 2, (C.tall ? C.H - 260 : C.H - 190), 14, 11, 1.38);
  const fit = { ...fit0, size: tplPlanned(C, "tweet", fit0.size) };
  return `<div style="position:absolute;inset:0;background:${tplBg(pick.ground)}"></div>`
    + `<div style="position:absolute;left:${left}px;right:${right}px;top:${C.tall ? "46%" : "50%"};transform:translateY(-50%);background:#FFFFFF;border-radius:12px;padding:${pad}px ${pad}px 13px;display:flex;flex-direction:column;gap:11px;box-shadow:0 1px 2px rgba(15,20,25,.05),0 16px 38px -18px rgba(15,20,25,.34);font-family:${TPL_SYS}">`
    + `<div style="display:flex;align-items:center;gap:9px"><span style="width:32px;height:32px;flex-shrink:0;border-radius:50%;background:#E6E7EB${C.avatar ? ` url('${tplEsc(C.avatar)}') center/cover no-repeat` : ""};color:#3F4349;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:600">${C.avatar ? "" : initial}</span>`
    + `<span style="flex:1;min-width:0;display:flex;flex-direction:column;gap:2px"><span style="display:flex;align-items:center;gap:3px;font-size:11.5px;font-weight:700;line-height:1.2;color:#0F1419">${tplEsc(C.brand)} ${TPL_BADGE.replace(/width="12" height="12"/, 'width="13" height="13"')}</span><span style="font-size:10.5px;line-height:1.2;color:#536471">${tplEsc(handle)}</span></span>`
    + `<svg width="13" height="13" viewBox="0 0 24 24" fill="#536471" aria-hidden="true"><circle cx="5" cy="12" r="1.7"></circle><circle cx="12" cy="12" r="1.7"></circle><circle cx="19" cy="12" r="1.7"></circle></svg></div>`
    + `<span style="font-size:${fit.size}px;line-height:1.38;color:#0F1419;letter-spacing:-.003em">${text}</span>`
    + `<span style="font-size:10px;color:#536471">8:14 AM</span><span style="height:1px;background:#EFF3F4"></span>`
    + `<div style="display:flex;justify-content:space-between;padding:0 4px">${TPL_TWEET_ICONS.replace(/width="12" height="12"/g, 'width="14" height="14"')}</div></div>`;
};
