// The same designs drawn small on a Text Style tile (LookChip). Ours, not
// the kit's: the words start at the left and keep to their lines, the
// captions sit in the middle of the strip, and a design that stacks a mark
// over its words (an emoji, a step band) puts it beside them instead.
const LOOK_CHIP_CSS = `.ch-look.ch-chip .sl{align-items:flex-start; text-align:left; padding:0}
.ch-look.ch-chip .sl.cap{top:50%; bottom:auto; transform:translateY(-50%)}
.ch-look.ch-chip .sl p{white-space:nowrap}
.ch-look.ch-chip .cap{max-width:none}
.ch-look.ch-chip .ovBox{display:flex; align-items:center; gap:.45em}
.ch-look.ch-chip .ovBox .emoji, .ch-look.ch-chip .ovBox .nband, .ch-look.ch-chip .ovBox .nunder, .ch-look.ch-chip .ovBox .ovLabel{margin:0}
.ch-look.ch-chip .fnEmo .emoji{display:inline-block; font-size:1.15em; margin:0 .3em 0 0; vertical-align:-.1em}
.ch-look.ch-chip .hkStack .dn{margin-left:.35em}`;
// The tiles' chips: one reading size for every design, so a rail compares
// looks, not sizes.
const CHIP_TYPE_PX = 15;
function escLook(s: any): string {
  return String(s).replace(/[&<>"]/g, (c: string) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" } as any)[c]);
}
function lumLook(h: string): number {
  const c = [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16) / 255)
    .map((v) => (v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function contrastLook(a: string, b: string): number {
  const l1 = lumLook(a), l2 = lumLook(b);
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}
// The kit's saved variable string, as a React style object. Softr will not take
// a raw CSS string on `style`, so each "--name:value" becomes a property.
function cssVarsOf(vars: string): React.CSSProperties {
  const out: any = {};
  String(vars || "").split(";").forEach((bit) => {
    const at = bit.indexOf(":");
    if (at < 0) return;
    const k = bit.slice(0, at).trim();
    if (!k.startsWith("--")) return;
    out[k] = bit.slice(at + 1).trim();
  });
  return out as React.CSSProperties;
}
// One variable out of the kit's own saved string.
function varOf(vars: string, name: string, fallback = ""): string {
  const m = new RegExp("--" + name + ":([^;]+)").exec(String(vars || ""));
  return m ? m[1].trim() : fallback;
}
// The words a design is drawn with: the card's own, split for the designs that
// want a first and a second line, with the longest word carrying the emphasis
// the way the kit's sample sentence does.
// ─── Hook lines that read the way a person would say them ───────────────────
// Karen, 2026-10-07: "hooks should be organized by line logically". The kit
// split every hook at its middle word and let the browser wrap the rest, so
// "Your Pricing Is / Why Clients Keep Ghosting / You". Here every place a line
// could break is scored and the best one wins: at a full stop or a comma
// first, never after a word that leans on the next one ("the", "your", "to"),
// rather before a word that opens a phrase ("why", "about", "you"), not
// between two words that belong together, never leaving one word alone on a
// line, and with the lines as even as those allow. Lines the person typed
// with Enter are kept exactly as typed.
const HOOK_LEANS = new Set(["a", "an", "the", "my", "your", "our", "their", "his", "her", "its", "to", "of", "in", "on", "at", "for", "with", "by", "from", "into", "onto", "about", "as", "than", "and", "or", "but", "nor", "not", "no", "very"]);
const HOOK_OPENS = new Set(["a", "an", "the", "my", "your", "our", "their", "his", "her", "its", "this", "that", "these", "those", "i", "you", "we", "they", "he", "she", "it", "to", "of", "in", "on", "at", "for", "with", "by", "from", "into", "about", "and", "but", "or", "so", "because", "why", "how", "what", "when", "who", "which", "where", "if", "than", "until", "while", "before", "after", "not", "never"]);
const HOOK_AUX = new Set(["is", "are", "was", "were", "be", "been", "am", "will", "can", "could", "should", "would", "do", "does", "did", "have", "has", "had", "don't", "doesn't", "didn't", "can't", "won't", "isn't", "aren't", "it's", "you're", "i'm", "that's"]);
const bareWord = (w: string) => String(w || "").toLowerCase().replace(/[’]/g, "'").replace(/[^\p{L}\p{N}']/gu, "");
function hookBreakCost(words: string[], starts: number[]): number {
  const bounds = [0, ...starts, words.length];
  const lens: number[] = [];
  for (let i = 0; i + 1 < bounds.length; i++) lens.push(words.slice(bounds[i], bounds[i + 1]).join(" ").length);
  const total = Math.max(1, words.join(" ").length);
  let cost = lens.length > 1 ? ((Math.max(...lens) - Math.min(...lens)) / total) * 12 : 0;
  starts.forEach((at) => { cost += breakScore(words, at); });
  if (words.length >= 4) lens.forEach((_, i) => { if (bounds[i + 1] - bounds[i] === 1) cost += 5; });
  return cost;
}
// What starting a new line at word `at` costs, on its own.
function breakScore(words: string[], at: number): number {
  const w = words[at - 1], v = words[at];
  const bw = bareWord(w), bv = bareWord(v);
  if (/[.!?…]["'”’)]*$/.test(w)) return -8;
  if (/[,;:—–-]["'”’)]*$/.test(w)) return -5;
  let cost = 0;
  if (HOOK_LEANS.has(bw)) cost += 8;
  const opens = HOOK_OPENS.has(bv) || /ly$/.test(bv);
  if (opens) cost -= 1.5;
  const loose = (x: string) => HOOK_LEANS.has(x) || HOOK_OPENS.has(x) || HOOK_AUX.has(x);
  if (!opens && !loose(bw) && !loose(bv)) cost += 3;
  return cost;
}
// ─── Text overlay lines ─────────────────────────────────────────────────────
// A text overlay runs 15 words, up to 30 (Karen, 2026-10-08), far longer than
// a hook, so two or three lines would make each one too long to read. Up to
// 60 letters it is cut like a hook (two lines, three when that reads better);
// past that it gets about one line per 22 letters, three to seven, broken by
// the same reading rules and kept close to even. Lines typed with Enter stay;
// a typed line that is still too long is broken further.
const OVERLAY_LINE = 22;
const OVERLAY_MAX_LINES = 7;
function overlayBreaks(words: string[], lines: number): number[] {
  const n = words.length;
  const k = Math.max(1, Math.min(lines, n));
  if (k === 1) return [];
  const len = (a: number, b: number) => words.slice(a, b).join(" ").length;
  const target = words.join(" ").length / k;
  const lineCost = (a: number, b: number) => { const d = (len(a, b) - target) / target; return 8 * d * d + (b - a === 1 ? 5 : 0); };
  // best[j][i]: the cheapest way to set the first i words as j lines.
  const best = Array.from({ length: k + 1 }, () => new Array(n + 1).fill(Infinity));
  const from = Array.from({ length: k + 1 }, () => new Array(n + 1).fill(-1));
  best[0][0] = 0;
  for (let j = 1; j <= k; j++) {
    for (let i = j; i <= n; i++) {
      for (let a = j - 1; a < i; a++) {
        if (!isFinite(best[j - 1][a])) continue;
        const c = best[j - 1][a] + lineCost(a, i) + (a > 0 ? breakScore(words, a) : 0);
        if (c < best[j][i]) { best[j][i] = c; from[j][i] = a; }
      }
    }
  }
  const starts: number[] = [];
  let i = n;
  for (let j = k; j > 1; j--) { const a = from[j][i]; starts.unshift(a); i = a; }
  return starts;
}
const overlayAuto = (words: string[]) => {
  const letters = words.join(" ").length;
  return letters <= 60 ? hookLines(words, [], 1)
    : overlayBreaks(words, Math.max(3, Math.min(OVERLAY_MAX_LINES, Math.round(letters / OVERLAY_LINE))));
};
function overlayLines(words: string[], typed: number[]): number[] {
  if (!typed.length) return overlayAuto(words);
  const out: number[] = [];
  const bounds = [0, ...typed, words.length];
  for (let i = 0; i + 1 < bounds.length; i++) {
    const a = bounds[i], b = bounds[i + 1];
    if (i > 0) out.push(a);
    const seg = words.slice(a, b);
    const letters = seg.join(" ").length;
    if (letters > 34) overlayAuto(seg).forEach((at) => out.push(a + at));
  }
  return out;
}
// Where each new line starts (word positions), for `lines` lines at most.
function hookBreaks(words: string[], lines: number): number[] {
  const n = words.length;
  const k = Math.max(1, Math.min(lines, n));
  if (k === 1) return [];
  let best: number[] = [], bestCost = Infinity;
  const pick = (from: number, left: number, chosen: number[]) => {
    if (left === 0) { const c = hookBreakCost(words, chosen); if (c < bestCost) { bestCost = c; best = chosen; } return; }
    for (let at = from; at <= n - left; at++) pick(at + 1, left - 1, [...chosen, at]);
  };
  pick(1, k - 1, []);
  return best;
}
// The longest line, in letters, for a set of line starts.
function hookLongest(words: string[], starts: number[]): number {
  const bounds = [0, ...starts, words.length];
  let most = 0;
  for (let i = 0; i + 1 < bounds.length; i++) most = Math.max(most, words.slice(bounds[i], bounds[i + 1]).join(" ").length);
  return most;
}
// How a hook is cut into lines: as typed; otherwise two lines (one for a
// short line in a design that allows it), and three when a long hook's one
// good break is far off centre, which would leave one long line and make the
// type small ("Your DMs are the content calendar / you never opened"). Six
// words or more go on three short lines too, so the hook can stand at about
// twice the captions' size (Karen, 2026-10-11).
function hookLines(words: string[], typed: number[], minLines: number): number[] {
  if (typed.length) return typed;
  const flat = words.join(" ").length;
  if (minLines < 2 && flat <= 16) return [];
  const two = hookBreaks(words, 2);
  if (words.length >= 6 || (flat > 36 && hookLongest(words, two) / flat > 0.6) || flat > 60) {
    const three = hookBreaks(words, 3);
    if (hookLongest(words, three) < hookLongest(words, two)) return three;
  }
  return two;
}
const LOOK_WORD_CAP = 40;
function lookWords(text: string): { HW: string[]; HE: number; typed: number[] } {
  // Lines typed with Enter are kept: `typed` holds where each one starts.
  const typed: number[] = [];
  const rawLines = String(text || "").trim().split(/\n+/).map((l) => l.trim().split(/\s+/).filter(Boolean)).filter((l) => l.length);
  const raw: string[] = [];
  // Up to 40 words: a text overlay may run to 30 (Karen, 2026-10-08), and the
  // old 16 cut the rest of the line off.
  rawLines.forEach((l) => { if (raw.length && raw.length < LOOK_WORD_CAP) typed.push(raw.length); l.forEach((w) => { if (raw.length < LOOK_WORD_CAP) raw.push(w); }); });
  // A word wrapped in asterisks is the one the design emphasises, with the
  // asterisks taken off (Karen, 2026-10-06: no new controls, the text carries
  // it). Without one, the longest word stands, as before.
  let marked = -1;
  const HW = raw.map((w, i) => {
    const m = /^(\W*)\*([^*]+)\*(\W*)$/.exec(w);
    if (!m) return w;
    if (marked < 0) marked = i;
    return m[1] + m[2] + m[3];
  });
  if (!HW.length) return { HW: ["Your", "words", "go", "here"], HE: 1, typed: [] };
  if (marked >= 0) return { HW, HE: marked, typed };
  let HE = 0, best = 0;
  HW.forEach((w, i) => { const n = w.replace(/[^A-Za-z0-9]/g, "").length; if (n > best) { best = n; HE = i; } });
  return { HW, HE, typed };
}
// `art` itself, exactly as the kit block writes it. Its own globals are made
// locals here: the words come from the card, the four colours it reads come
// out of the kit's saved variables.
// `num` is the number a numbered label design shows: each list label carries
// its own place in the list (2026-10-11), where the kit's sample always read 1.
function lookArt(group: string, id: string, text: string, vars: string, num = "1"): string {
  const w = lookWords(text);
  const HW = w.HW, HE = w.HE;
  // Where a hook's lines start: as typed, or at the best reading breaks
  // (hookLines). A two-line design always takes two or more. A one-paragraph
  // design may keep a short hook on one line (Karen, 2026-10-07).
  const BR2 = hookLines(HW, w.typed, 2);
  const BRP = hookLines(HW, w.typed, 1);
  const joinAt = (a: number, b: number, starts: number[]) => {
    let o = "";
    for (let i = a; i < b; i++) o += (i > a ? (starts.includes(i) ? "<br>" : " ") : "") + escLook(HW[i]);
    return o;
  };
  const CAP = String(text || "").replace(/\*/g, "").trim() || "Your words go here";
  // Every word of the line. The kit cut a text overlay to five words and an
  // item to four, for its own sample, so a card's longer overlay lost its
  // end the same way the hooks did (fixed for hooks 2026-10-06, here too).
  const NUM = { n: String(num || "1"), t: HW.join(" ") };
  const OVT = HW.join(" ");
  const EMO = "\u2726";
  const S: any = {
    hi: varOf(vars, "highlight", "#A855F7"),
    con: varOf(vars, "block", "#3F3F46"),
    hookAccent: varOf(vars, "hook-accent", varOf(vars, "highlight", "#A855F7")),
    motif: varOf(vars, "motif", "none") === "none" ? null : varOf(vars, "motif"),
    photoNeutral: varOf(vars, "photo-neutral", "#FFFFFF"),
  };
  const esc = escLook;
  const contrast = contrastLook;
  const separated = (a: string, b: string) => Math.abs(lumLook(a) - lumLook(b)) >= 0.20;
  const em = (word: string, style: string) => '<span class="em ' + style + '">' + esc(word) + "</span>";
  const line = (style: string) => {
    let o = "";
    for (let i = 0; i < HW.length; i++) o += (i ? (BRP.includes(i) ? "<br>" : " ") : "") + (i === HE ? em(HW[i], style) : esc(HW[i]));
    return o;
  };
  const line2 = (style: string, second: number) => {
    let o = "";
    for (let i = 0; i < HW.length; i++) o += (i ? (BRP.includes(i) ? "<br>" : " ") : "") + (i === HE ? em(HW[i], style) : i === second ? em(HW[i], "tint") : esc(HW[i]));
    return o;
  };
  const emInSlab = () => (separated(S.hi, S.con) ? "tint" : "");
  const tick = 0;
  void CAP; void NUM; void OVT; void EMO; void emInSlab; void line2; void tick;

  function art(group, id, tick){
    if(group === "hook"){
      /* The kit indexes words by POSITION, for its eight-word sample sentence.
         A card's hook is any length, so every word is kept (Karen, 2026-10-06:
         "why is it that some visual hook options don't show the full text?")
         and the lines break where the hook reads, not at its middle word
         (hookBreaks, Karen 2026-10-07). Each line stays one line ("nw"): the
         fit in LookFit sizes the type to the lines, never the reverse. */
      var n = HW.length;
      var cut = function(a, b){ return esc(HW.slice(a, b).join(" ")); };
      var C = esc(HW[n - 1] || "");
      /* ---- the hook set: ORGANIC g1-g6 (black and white), LOUD h1-h10 ---- */
      var f = BR2.length ? BR2[0] : n;
      var HL1 = joinAt(0, f, BR2), HL2 = joinAt(f, n, BR2);
      var LAST = esc(HW[n - 1] || "");
      var SENT = joinAt(0, n, BRP);
      var two = function(cls){ return '<div class="sl"><p class="tx sh hkT nw ' + cls
        + '"><span class="l1">' + HL1 + '</span><span class="l2">' + HL2 + "</span></p></div>"; };
      /* A one-word line has no second band: an empty one drew a sliver of
         colour under the word (2026-10-07). */
      var band = function(cls, kind){ return '<div class="sl"><p class="tx nw ' + kind + ' hkT ' + cls
        + '"><span class="bd">' + HL1 + "</span>" + (HL2 ? '<br><span class="bd">' + HL2 + "</span>" : "") + "</p></div>"; };
      var outb = function(cls){ return '<div class="sl"><p class="tx hkT hkOutB nw ' + cls + '">'
        + HL1 + (HL2 ? "<br>" + HL2 : "") + "</p></div>"; };
      /* ORGANIC - no colour anywhere; case, weight, backing and outline only */
      if(id==="g1") return two("ttl");
      if(id==="g2") return two("upp");
      if(id==="g3") return band("ttl", "hkBack");
      if(id==="g4") return band("upp", "hkBack");
      if(id==="g5") return outb("ttl");
      if(id==="g6") return outb("upp");
      /* the plain one: the biggest type in the kit, white, no backing and no
         outline. Its B variation is the same words in caps, which the kit sets
         through --big-case rather than a second markup path. */
      if(id==="g7") return '<div class="sl"><p class="tx sh hkT hkBig nw">' + HL1 + (HL2 ? "<br>" + HL2 : "") + "</p></div>";
      /* LOUD - exactly one brand colour per design */
      if(id==="h1") return band("upp", "hkBand");
      /* The kicker is the first line, the slab the last, and any line between
         sits between them, each phrase kept whole ("ph" and the slab do not
         wrap). The same rule as the Brand Kit screen (2026-10-07). */
      var kEnd = BR2.length ? BR2[0] : 0, sFrom = BR2.length ? BR2[BR2.length - 1] : 0;
      var KK = joinAt(0, kEnd, BR2), KB = joinAt(kEnd, sFrom, BR2), MK = joinAt(sFrom, n, BR2);
      if(id==="h2") return '<div class="sl"><p class="tx sh hkT hkKick ttl">' + (KK ? '<span class="kk">' + KK + "</span>" : "")
        + (KB ? '<span class="ph">' + KB + "</span> " : "") + '<span class="mk">' + MK + "</span></p></div>";
      /* The stacks once showed only the last two words. Now the first line
         stacks over the second, so every word is there (2026-10-07). */
      if(id==="h3") return '<div class="sl"><p class="tx hkT hkStack nw"><span class="up">' + HL1
        + "</span>" + (HL2 ? '<span class="dn">' + HL2 + "</span>" : "") + "</p></div>";
      if(id==="h4") return '<div class="sl"><p class="tx hkT hkStack nu nw"><span class="up">' + HL1
        + "</span>" + (HL2 ? '<span class="dn">' + HL2 + "</span>" : "") + "</p></div>";
      /* The last word carries the accent, on the second line when there is
         one. A one-word line draws its word once (2026-10-07). */
      var lastLine = function(){
        var em1 = '<span class="em">' + LAST + "</span>";
        if (n <= 1) return em1;
        if (f >= n) return joinAt(0, n - 1, BRP) + (BRP.indexOf(n - 1) > 0 ? "<br>" : " ") + em1;
        var mid = joinAt(f, n - 1, BR2);
        return HL1 + "<br>" + (mid ? mid + (BR2.indexOf(n - 1) > 0 && n - 1 > f ? "<br>" : " ") : "") + em1;
      };
      if(id==="h5") return '<div class="sl"><p class="tx sh hkT hkUnd2 upp nw">' + lastLine() + "</p></div>";
      if(id==="h6") return '<div class="sl"><p class="tx sh hkT hkIt2 nw">' + lastLine() + "</p></div>";
      if(id==="h7") return '<div class="sl"><p class="tx sh hkT hkIt2 nu nw">' + lastLine() + "</p></div>";
      /* the stroke thins when it sits too close to the neutral it cuts */
      var thin = contrast(S.photoNeutral || "#FFFFFF", S.hookAccent || S.hi) < 1.8 ? " sub" : "";
      if(id==="h8") return '<div class="sl"><p class="tx hkT hkOutC upp nw' + thin + '">'
        + HL1 + (HL2 ? "<br>" + HL2 : "") + "</p></div>";
      if(id==="h9") return '<div class="sl"><p class="tx hkT hkOutC snt nw' + thin + '">' + SENT + "</p></div>";
      if(id==="h10") return '<div class="sl"><p class="tx sh hkT hkFill snt nw">' + SENT + "</p></div>";

      if(id==="f1") return '<div class="sl"><p class="tx fn1 nw">' + line("") + "</p></div>";
      if(id==="f2") return '<div class="sl"><p class="tx fn2 nw"><span class="a">'
        + HL1 + "</span>" + (HL2 ? '<br><span class="b">' + HL2 + "</span>" : "") + "</p></div>";
      /* The marked word is the one before last, unless the heavy opening
         already holds it: a two-word line used to draw its first word twice.
         Its four parts wrap freely, so the spaces inside a phrase do not
         break (2026-10-07): a line can only end where the hook reads. */
      var q4 = Math.max(1, Math.ceil(n / 4)), mi = n - 2 >= q4 ? n - 2 : -1;
      var gap = function(i){ return BRP.indexOf(i) >= 0 ? " " : "\u00a0"; };
      var run = function(a, b){ var o = ""; for (var i = a; i < b; i++) o += (i > a ? gap(i) : "") + esc(HW[i]); return o; };
      var loEnd = mi >= 0 ? mi : n - 1;
      if(id==="f3") return '<div class="sl"><p class="tx sh fn3"><span class="hv">' + run(0, q4) + "</span>"
        + (loEnd > q4 ? gap(q4) + '<span class="lo">' + run(q4, loEnd) + "</span>" : "")
        + (mi >= 0 ? gap(mi) + em(HW[mi], "mark") : "")
        + (n > q4 ? gap(n - 1) + C : "") + "</p></div>";
      if(id==="f4") return '<div class="sl"><p class="tx sh fn4 nw"><span class="spark">'
        + '<s>\u2726</s><s>\u2727</s><s>\u22C6</s><s>\u2726</s>' + line("tint") + "</span></p></div>";
      if(id==="f5") return '<div class="sl"><p class="tx sh fnEmo nw"><span class="emoji">' + EMO
        + "</span>" + line("tint") + "</p></div>";
      /* f6 stacked caps: one word marked on the highlighter, a second tinted */
      if(id==="f6") return '<div class="sl"><p class="tx sh hk1 nw">' + line2("mark", 1) + "</p></div>";
      if(id==="f6") return '<div class="sl"><p class="tx sh fnStack"><span class="up">'
        + esc(HW[0]) + '</span><span class="dn">'
        + esc(HW[1]) + "</span></p></div>";

      /* organic: one size throughout - varied by shadow, bold and italic only */
      var L1 = HL1, L2 = HL2;
      function wordAs(cls){
        var o = "";
        for(var i=0;i<HW.length;i++)
          o += (i?" ":"") + (i===HE ? '<span class="' + cls + '">' + esc(HW[i]) + "</span>" : esc(HW[i]));
        return o;
      }
      if(id==="g1") return '<div class="sl"><p class="tx sh og">' + wordAs("b") + "</p></div>";
      if(id==="g2") return '<div class="sl"><p class="tx sh og"><span class="ln">' + L1
        + '</span><span class="ln b">' + L2 + "</span></p></div>";
      if(id==="g3") return '<div class="sl"><p class="tx sh og">' + wordAs("i") + "</p></div>";
      if(id==="g4") return '<div class="sl"><p class="tx sh og"><span class="ln">' + L1
        + '</span><span class="ln i">' + L2 + "</span></p></div>";
      if(id==="g5") return '<div class="sl"><p class="tx shDeep og">' + wordAs("b") + "</p></div>";
      return '<div class="sl"><p class="tx sh og"><span class="ln i">' + L1
        + '</span><span class="ln b">' + L2 + "</span></p></div>";
    }

    if(group === "captions"){
      /* Five designs, the TikTok way (Karen, 2026-10-11). Classic (white, a
         thin black outline), Classic glass (white on a dark panel) and Box
         (a box in a brand colour) show a few words at once ("still"); Karaoke
         and Karaoke glass light the word being said. One line of up to five
         words. A retired design draws as the one that replaced it. */
      var ALIAS = {s2:"s1", s3:"s1", c2:"c1", c3:"c1", c4:"c1", n2:"n1", n3:"n1"};
      var cid = ALIAS[id] || id;
      var ph = CAP.split(/\s+/).slice(0,5);
      var STILL = {s1:"cap outl still", c1:"cap glass still", b1:"cap acc still"};
      if(STILL[cid]) return '<div class="sl cap"><p class="' + STILL[cid] + '">' + esc(ph.join(" ")) + "</p></div>";
      var t = "";
      for(var j=0;j<ph.length;j++)
        t += (j?" ":"") + '<span class="kw" style="--ci:' + j + '">' + esc(ph[j]) + "</span>";
      return '<div class="sl cap"><p class="' + (cid === "b2" ? "cap glass kar" : "cap kar") + '" style="--cn:' + ph.length + '">' + t + "</p></div>";
    }

    if(group === "overlay"){
      if(id.charAt(0) === "p")
        return '<div class="ovPic f' + id.slice(1) + '">' + (id==="p3"?"<i></i>":"") + "</div>";
      if(id==="m1"||id==="m2"||id==="m5")
        return '<div class="sl"><div class="ovBox"><div class="nrow '
          + (id==="m2"?"n2":id==="m5"?"n5":"") + '"><span class="mk">' + NUM.n
          + '</span><p class="ntx">' + esc(NUM.t) + "</p></div></div></div>";
      if(id==="m3") return '<div class="sl"><div class="ovBox"><span class="nband">Step ' + NUM.n
        + '</span><p class="ntx">' + esc(NUM.t) + "</p></div></div>";
      if(id==="m4") return '<div class="sl"><div class="ovBox"><span class="emoji">' + EMO
        + '</span><p class="ntx tint">' + NUM.n + ". " + esc(NUM.t) + "</p></div></div>";
      if(id==="m6") return '<div class="sl"><div class="ovBox"><span class="nunder">' + NUM.n
        + '</span><p class="ntx">' + esc(NUM.t) + "</p></div></div>";
      /* A text overlay breaks into lines where it reads, like a hook, and
         each line stays one line: the type is sized to the lines, which is
         the guidelines' "the longest paragraph sits on one line" (2026-10-07). */
      var OVL = joinAt(0, HW.length, overlayLines(HW, w.typed));
      if(id==="t1") return '<div class="sl"><div class="ovBox panel"><p class="tOnly nw">' + OVL + "</p></div></div>";
      if(id==="t2") return '<div class="sl"><div class="ovBox"><p class="tOnly nw">' + OVL + "</p></div></div>";
      if(id==="t3") return '<div class="sl"><div class="ovBox"><p class="tOnly rule nw">' + OVL + "</p></div></div>";
      if(id==="t4") return '<div class="sl"><div class="ovBox"><span class="emoji">' + EMO
        + '</span><p class="tOnly tint nw">' + OVL + "</p></div></div>";
      if(id==="t5") return '<div class="sl"><div class="ovBox"><p class="tOnly under nw">' + OVL + "</p></div></div>";
      return '<div class="sl"><div class="ovBox"><span class="ovLabel">Next step</span><p class="tOnly nw">'
        + OVL + "</p></div></div>";
    }

    /* static posts: background only, no text */
    /* exactly one grain option and one brand-element option in each bucket */
    var BG = {
      L1:"bgL",           L2:"bgL2",           L3:"bgLGray",
      L4:"bgLTwo",        L5:"bgLRamp",        L6:"bgLAccent",  L7:"bgL vl vlL",
      L8:"bgLGrad",       L9:"bgLGrad bgLGradGr",
      D1:"bgD onDark",    D2:"bgD2 onDark",    D3:"bgDGray onDark",
      D4:"bgDTwo onDark", D5:"bgDRamp onDark", D6:"bgDAccent onDark", D7:"bgD onDark vl vlD",
      D8:"bgDGrad onDark", D9:"bgDGrad bgDGradGr onDark",
      F1:"bgFunGrad onDark",  F2:"bgFunPair onDark", F3:"bgFunPair2 onDark",
      F4:"bgFunHi1",          F5:"bgFunHi2",         F6:"bgSplit", F7:"bgAngle",
      F8:"bgD onDark aurora blend", F9:"bgD onDark aurora2 blend"
    };
    var cls = BG[id] || "bgL";
    var brand = /brand/.test(cls)
      ? (S.motif ? '<span class="brandEl"></span>'
                 : '<span class="needEl">Upload a brand element on General</span>')
      : "";
    return '<div class="post ' + cls + '">' + brand + "</div>";
  }
  return art(group, id, tick);
}

// ─── The preview's design, held to the strict margins and its size caps ─────
// The kit sizes everything in cqw, so the design is drawn on a STAGE that is
// narrower than the phone by `scale`: every size shrinks with it, while the
// box the words sit in stays the phone's safe box. The fit starts at the
// design's own size and steps down until the drawing sits inside the safe
// box, under its layer's share of the screen and, for a hook or a call to
// action, under the type ceiling. A hook or a call to action then steps up
// again for as long as all of that still holds.
// Where the letters actually are: one box per run of text, read through a
// Range, which follows text that overflows its element. Pages without layout
// (the test harness) have no Range boxes and skip it.
function inkOfText(root: Element | null, add: (R: any) => void) {
  if (!root || typeof document === "undefined" || typeof document.createRange !== "function") return;
  const range = document.createRange();
  if (typeof (range as any).getBoundingClientRect !== "function") return;
  const walk = document.createTreeWalker(root, 4 /* NodeFilter.SHOW_TEXT */);
  for (let n = walk.nextNode(); n; n = walk.nextNode()) {
    if (!String(n.textContent || "").trim()) continue;
    range.selectNodeContents(n);
    add(range.getBoundingClientRect());
  }
}
function LookFit({ html, vars, layer, typeCapPx, onFit, hidden }: { html: string; vars: string; layer: string; typeCapPx?: number; onFit?: (typePx: number) => void; hidden?: boolean }) {
  const frameRef = useRef<HTMLSpanElement | null>(null);
  const stageRef = useRef<HTMLSpanElement | null>(null);
  const [scale, setScale] = useState(1);
  // A brand font that arrives late changes every measurement, so the fit runs
  // again when one does.
  const [fontTick, setFontTick] = useState(0);
  useEffect(() => {
    const fonts: any = typeof document !== "undefined" ? (document as any).fonts : null;
    if (!fonts || typeof fonts.addEventListener !== "function") return;
    const again = () => setFontTick((n) => n + 1);
    fonts.addEventListener("loadingdone", again);
    if (fonts.ready && typeof fonts.ready.then === "function") fonts.ready.then(again).catch(() => {});
    return () => fonts.removeEventListener("loadingdone", again);
  }, []);
  // Captions sit at the bottom, which is where the platform's buttons are.
  const low = layer === "captions";
  const right = low ? SAFE_RAIL : SAFE_SIDE;
  const pct = (v: number) => `${Math.round(v * 100000) / 1000}%`;
  const stageAt = (s: number): Record<string, string> => {
    const side = (1 - s) / 2;
    return {
      left: pct(side),
      width: pct(s),
      "--sl": pct((SAFE_SIDE - side) / s),
      "--sr": pct((right - side) / s),
    };
  };
  useLayoutEffect(() => {
    const frame = frameRef.current, stage = stageRef.current;
    if (!frame || !stage || !html) return;
    const F = frame.getBoundingClientRect();
    const W = F.width, H = F.height;
    // No layout (a test page, a hidden tab): draw at the design's own size.
    if (!(W > 0) || !(H > 0)) { if (scale !== 1) setScale(1); return; }
    const put = (s: number) => {
      const at = stageAt(s);
      Object.keys(at).forEach((k) => stage.style.setProperty(k, at[k]));
    };
    // A text overlay sizes itself too, both ways (video-editing-guidelines.md:
    // "less text means bigger type"), held under the hook: its type at most
    // the closing's share of the hook's ceiling, its area its own 20%.
    // A list label sizes itself too (2026-10-11), measured by its words, not
    // its number, which is bigger by design.
    const isHook = layer === "hook" || layer === "cta" || layer === "overlay";
    const sized = isHook || layer === "items";
    const typeMax = layer === "cta"
      ? Math.min(HOOK_TYPE_MAX * W, typeCapPx && typeCapPx > 0 ? typeCapPx : CLOSING_SCALE * HOOK_TYPE_MAX * W)
      : layer === "overlay" ? CLOSING_SCALE * HOOK_TYPE_MAX * W
      : layer === "items" ? ITEMS_TYPE_MAX * W
      : HOOK_TYPE_MAX * W;
    const typeMin = Math.min(typeMax, (TYPE_MIN[layer] || 0) * W);
    const ink = () => {
      let l = Infinity, t = Infinity, r = -Infinity, b = -Infinity, type = 0;
      const add = (R: { left: number; top: number; right: number; bottom: number; width: number; height: number }) => {
        if (R.width > 0 && R.height > 0) { l = Math.min(l, R.left); t = Math.min(t, R.top); r = Math.max(r, R.right); b = Math.max(b, R.bottom); }
      };
      (Array.from(stage.querySelectorAll(".sl *")) as HTMLElement[]).forEach((el) => {
        add(el.getBoundingClientRect());
        // The type ceiling is about words, not an emoji or a sparkle.
        const words = layer === "items" ? (el.classList.contains("ntx") || el.classList.contains("tOnly")) : !el.classList.contains("emoji") && el.tagName !== "S";
        if (sized && words && Array.from(el.childNodes).some((c) => c.nodeType === 3 && String(c.textContent || "").trim())) {
          type = Math.max(type, parseFloat(getComputedStyle(el).fontSize) || 0);
        }
      });
      // The words themselves, not just their boxes: a line that cannot wrap
      // runs out past its box, and measuring only the box let a long text
      // overlay look like it fit while it spilled over the margin (Karen,
      // 2026-10-08, screenshot of a 15-word overlay over the face).
      inkOfText(stage.querySelector(".sl"), add);
      return { l, t, r, b, type };
    };
    const fits = (k: ReturnType<typeof ink>) => {
      if (!isFinite(k.l)) return true;
      const inside = k.l >= F.left + SAFE_SIDE * W - 0.5 && k.r <= F.right - right * W + 0.5
        && k.t >= F.top + SAFE_TOP * H - 0.5 && k.b <= F.bottom - SAFE_BOTTOM * H + 0.5;
      const share = ((k.r - k.l) * (k.b - k.t)) / (W * H * USABLE_SHARE);
      const cap = (LAYER_CAP[layer] ?? 0.2) * (sized && k.type > 0 && k.type <= typeMin + 0.25 ? ROOMY_SHARE : 1);
      return inside && share <= cap && (!sized || k.type <= typeMax + 0.25);
    };
    let s = 1;
    put(s);
    let k = ink();
    // The type ceiling is a straight ratio, so it is met in one step.
    if (sized && k.type > typeMax) { s = Math.max(0.3, typeMax / k.type); put(s); k = ink(); }
    for (let i = 0; i < 40 && !fits(k) && s > 0.3; i++) { s = Math.max(0.3, s * 0.95); put(s); k = ink(); }
    // A hook, and the call to action that follows it, may also GROW past the
    // design's own size, up to the same limits: the type ceiling, the safe
    // box and its share of the screen (Karen, 2026-10-07: "it's ok to
    // increase the size but not ... surpass the approved area"). Keeping it
    // off the face is the edit's placement step, which knows the shot.
    if (sized && isFinite(k.l) && fits(k)) {
      for (let i = 0; i < 80 && s < 3; i++) {
        const t = s * 1.02;
        put(t);
        if (!fits(ink())) { put(s); break; }
        s = t;
      }
      // The last step can stop just short of the smallest size: try it exactly.
      k = ink();
      if (k.type > 0 && k.type < typeMin - 0.25) { const t = s * typeMin / k.type; put(t); if (fits(ink())) s = t; else put(s); }
    }
    if (Math.abs(s - scale) > 0.0005) setScale(s);
    // The hook reports its type size, which the closing is held under.
    if (onFit) onFit(ink().type);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [html, vars, layer, fontTick, typeCapPx]);
  return (
    <span ref={frameRef} className="ch-look" aria-hidden="true" style={{ position: "absolute", inset: 0, display: "block", overflow: "hidden", visibility: hidden ? "hidden" : undefined }}>
      <span ref={stageRef} data-fit={scale.toFixed(3)}
        style={{ position: "absolute", top: 0, bottom: 0, display: "block", containerType: "inline-size", ["--st" as any]: "13.0%", ["--sb" as any]: "19.8%", ...stageAt(scale), ...cssVarsOf(vars) } as any}
        dangerouslySetInnerHTML={{ __html: html }} />
    </span>
  );
}

// ─── A design's own name, drawn in the design, for a Text Style tile ────────
// Karen, 2026-10-07: "perhaps making the dropdown option itself styled?"; the
// dropdowns became rails of these tiles on 2026-10-20. The
// kit's own markup and colours on a strip of dark footage, the type brought to
// one reading size (CHIP_TYPE_PX) whatever the design's own scale. `tag` is the
// A or B of a design offered in both of the kit's colour readings.
function LookChip({ html, vars, tag, on }: { html: string; vars: string; tag?: string; on?: boolean }) {
  const stageRef = useRef<HTMLSpanElement | null>(null);
  const [base, setBase] = useState(200);
  useLayoutEffect(() => {
    const el = stageRef.current;
    if (!el) return;
    const p = el.querySelector(".sl p") as HTMLElement | null;
    const fs = p ? String(getComputedStyle(p).fontSize || "") : "";
    if (!/px$/.test(fs)) return;
    const px = parseFloat(fs);
    if (!(px > 0)) return;
    const want = Math.max(110, Math.min(320, Math.round((base * CHIP_TYPE_PX) / px)));
    if (Math.abs(want - base) > 1) setBase(want);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [html]);
  return (
    <span className="ch-look ch-chip" aria-hidden="true"
      style={{ position: "relative", display: "block", height: "46px", borderRadius: "8px", overflow: "hidden", background: "linear-gradient(135deg, #2D313B 0%, #16181D 100%)", boxShadow: on ? `0 0 0 2px ${PICK}` : "inset 0 0 0 1px rgba(255,255,255,0.04)" }}>
      <span ref={stageRef}
        style={{ position: "absolute", top: 0, bottom: 0, left: "14px", width: `${base}px`, display: "block", containerType: "inline-size", ["--sl" as any]: "0%", ["--sr" as any]: "0%", ["--st" as any]: "0%", ["--sb" as any]: "0%", ...cssVarsOf(vars) } as any}
        dangerouslySetInnerHTML={{ __html: html }} />
      {(tag || on) && (
        <span style={{ position: "absolute", right: "10px", top: "50%", transform: "translateY(-50%)", display: "inline-flex", alignItems: "center", gap: "7px", padding: "0 0 0 10px", background: "linear-gradient(90deg, rgba(22,24,29,0) 0%, #16181D 30%)" }}>
          {tag && <span style={{ fontFamily: MONO, fontSize: "10.5px", fontWeight: 500, letterSpacing: "0.08em", color: "rgba(255,255,255,0.72)", lineHeight: 1 }}>{tag}</span>}
          {on && <Check size={14} strokeWidth={3} color="white" />}
        </span>
      )}
    </span>
  );
}

function initialsOf(name: string): string {
  const parts = String(name || "").trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return "?";
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

// Airtable dates come as "YYYY-MM-DD"; read them as local calendar days so a
// deadline never shifts by a day across time zones.
function parseDay(v: any): Date | null {
  if (!v) return null;
  const s = String(v).slice(0, 10);
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) { const d = new Date(v); return isNaN(d.getTime()) ? null : d; }
  return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
}
function dayDiff(from: Date, to: Date): number {
  const a = new Date(from.getFullYear(), from.getMonth(), from.getDate()).getTime();
  const b = new Date(to.getFullYear(), to.getMonth(), to.getDate()).getTime();
  return Math.round((b - a) / 86400000);
}
// A deadline still ahead reads relative ("In 3 days"). One already past reads
// as its date ("Sep 12"), and the red colour is what says it is late (Karen,
// 2026-09-14: no "Overdue by n days").
function dueLabelFor(v: any): string {
  const d = parseDay(v);
  if (!d) return "";
  const n = dayDiff(new Date(), d);
  if (n === 0) return "Today";
  if (n === 1) return "Tomorrow";
  if (n > 1) return `In ${n} days`;
  const sameYear = d.getFullYear() === new Date().getFullYear();
  return d.toLocaleDateString("en-US", sameYear ? { month: "short", day: "numeric" } : { month: "short", day: "numeric", year: "numeric" });
}
function shortDate(v: any): string {
  const d = v ? new Date(v) : null;
  if (!d || isNaN(d.getTime())) return "";
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
}

// ─── Reading a card ──────────────────────────────────────────────────────────
type Owner =
  | { kind: "flowy"; key: "flowy"; name: "Flowy" }
  | { kind: "person"; key: string; name: string; initials: string }
  | { kind: "none"; key: "none"; name: "Unassigned" };

type Card = {
  id: string;
  rec: any;
  heading: string;
  format: string;
  isGraphic: boolean;
  status: HubStatus;
  rawStatus: string;
  owner: Owner;
  brandId: string;
  brandName: string;
  // The card's Delivery Style (its tag on the board) and when it was made
  // (the footer's "3 days ago"), Karen 2026-10-23.
  deliveryStyle: string;
  subformat: string;
  created: number;
  sessionId: string;
  dueDate: Date | null;
  dueLabel: string;
  overdue: boolean;
  // Airtable's own rollup. Kept on the card for sorting and for anything that
  // wants a raw total; every NUMBER a person sees comes from openCommentsOf.
  comments: number;
  rawCount: number;
  pillar: string;
  versionCount: number;
  handedOver: Date | null;
  approvedOn: string;
  lastUpdate: number;
  slides: string;
  duration: string;
  // Flowy is cutting or designing it right now.
  flowyWorking: boolean;
  // What went wrong with Flowy's last job, in plain words, and which kind it
  // is: "needs" when the person has to fix something (the clip, the words),
  // "failed" when it was Flowy's own fault and Try again is all there is
  // (Karen, 2026-10-08). Empty when all is well.
  flowyIssue: string;
  flowyIssueKind: "needs" | "failed" | "";
  // Flowy finished and saved the cut, but the card never moved on: the way
  // forward is moving it, not editing it again (2026-10-13).
  flowyUnfiled?: boolean;
  // When the edit was sent to Flowy (0 if never), which tells one edit from
  // the next when the worker loses one (2026-10-12).
  flowySentAt: number;
  // The last design went on the Template route (about 20 seconds), not
  // Custom Design (four to six minutes).
  flowyTemplate?: boolean;
  // A finished Clean Multiclip that still runs over 1:30 after everything
  // Flowy could cut, in plain words, shown while it waits for approval
  // (Karen, 2026-10-09). Empty otherwise.
  flowyLong: string;
};

// How long a design usually takes, for its bar: a template about 20 seconds,
// Custom Design four to six minutes (2026-10-20).
const FLOWY_TEMPLATE_MS = 25000;
const FLOWY_DESIGN_MS = 300000;
// A job that has not come back in this long is treated as lost. A Loop Broll
// takes under a minute.
const FLOWY_STALE_MS = 20 * 60 * 1000;
// Sooner when the worker says it has never heard of the edit: it restarted
// after the edit was sent, or the edit is this old and still unknown (Karen,
// 2026-10-12: a lost edit took twenty minutes to say so).
const FLOWY_UNKNOWN_MS = 150 * 1000;
const FLOWY_LOST_NOTE = (graphic: boolean) => (graphic ? "Flowy didn't finish this design. Try again." : "Flowy didn't finish this edit. Try again.");
// The worker finished and handed the cut to n8n, but the card never moved on
// (2026-10-13: Airtable was busy, FE2 saved the version and could not move
// the card). After this long the bar stops and the card says what to do.
const FLOWY_UNFILED_MS = 90 * 1000;
const FLOWY_UNFILED_NOTE = (graphic: boolean) => (graphic
  ? "Flowy finished and saved the new design, but the card couldn't move on. Move it to Approve Media."
  : "Flowy finished and saved the new version, but the card couldn't move on. Move it to Approve Media.");
// Flowy's notes inside "Flowy edit order": `sentAt`, written by the Edit
// button, `failed`, written by n8n FE2 when the worker gives up, and `long`,
// written by FE2 when a finished edit could not get down to 1:30.
function flowyNotesOf(v: any): { sentAt: number; failed: string; kind: "needs" | "failed"; long: string; template: boolean } {
  try {
    // Read raw, as the record window does: cleaning it as rich text would eat
    // anything in the reason that looks like a tag and break the JSON.
    const o = JSON.parse(String(v == null ? "" : v).trim() || "{}");
    const at = o && o.sentAt ? Date.parse(String(o.sentAt)) : NaN;
    const why = o && o.failed && typeof o.failed === "object" ? String(o.failed.reason || "").trim() : "";
    // n8n FE2 says which kind it is; an older note without one was Flowy's.
    const kind = o && o.failed && o.failed.kind === "needs" ? "needs" : "failed";
    const longOnly = o && o.long && typeof o.long === "object" ? String(o.long.reason || "").trim() : "";
    // Overlay pictures Flowy couldn't place (n8n FE2, Karen 2026-10-15).
    const pics = o && o.pictures && typeof o.pictures === "object" ? String(o.pictures.reason || "").trim() : "";
    const long = [longOnly, pics].filter(Boolean).join(" ");
    return { sentAt: isFinite(at) ? at : 0, failed: why || (o && o.failed ? "Flowy couldn't finish this edit. Try again." : ""), kind, long, template: !!(o && o.template) };
  } catch (e) { return { sentAt: 0, failed: "", kind: "failed", long: "", template: false }; }
}

const isGraphicRecord = (f: any) =>
  selectLabel(f?.contentType) === "Graphic"
  || GRAPHIC_FORMATS.includes(String(selectLabel(f?.format) || "").trim());

function hubStatusOf(f: any): HubStatus {
  const isGraphic = isGraphicRecord(f);
  // One field says where a card is (Karen, 2026-09-27), in its own words.
  const stage = selectLabel(f?.stage).trim();
  if (stage && (HUB_STATUSES as string[]).includes(stage)) return stage as HubStatus;
  if (stage && OLD_STATUS[stage]) return OLD_STATUS[stage];
  // The four old fields are still written beside it, so they answer for any
  // record the stage has not reached yet.
  const phase = selectLabel(f?.status);
  const pp = selectLabel(f?.postProductionStatus).trim().toLowerCase();
  if (phase === "Ready to Post" || phase === "Scheduled" || phase === "Posted") return "To Schedule";
  if (pp === "approved" || pp === "ready to post") return "To Schedule";
  if (pp === "to approve") return "Approve Media";
  if (pp === "in progress") return "In Progress";
  if (selectLabel(f?.shootingStatus) === "Shot Taken" && !allLinks(f?.scriptFiles).length) return "Attach Raw";
  return isGraphic ? "To Design" : "To Edit";
}

// The five labels the board shows, and what each one writes back. Airtable's
// Post-production status has its own older option names, so changing the
// status here writes the option that reads back as the label you picked:
// a graphic waiting to be made sits in To Design, a video in Creatives Queue
// (Airtable's spelling, no apostrophe). The phase field is left alone.
// Every stage the backend has, in the order the work runs. The board OFFERS
// all of them; which ones it SHOWS is the status filter's business
// (Karen, 2026-09-28).
const HUB_STATUSES: HubStatus[] = [
  "Script", "Review Script", "Shoot", "Attach Raw", "To Design", "To Edit",
  "In Progress", "Need Changes", "Approve Media", "Approve Post", "To Schedule", "Scheduled", "Published", "Publish Failed",
];
// What the board starts on: the work that belongs to this studio.
const STUDIO_FILTER: string[] = ["To Edit", "To Design", "In Progress", "Need Changes", "Approve Media", "Approve Post", "To Schedule"];
// Edit and Design follow their videos and graphics all the way to To
// Schedule, not just to Approve Media (Karen, 2026-10-08: "it doesn't make
// much sense to not have all the statuses").
function defaultStages(tab: Tab): string[] {
  return [...TAB_STAGES[tab]];
}
// The stages before footage exists. Since the boards merged the card stays
// on this board and simply moves to the Script or Shoot tab.
const AWAY_STAGES: string[] = ["Script", "Review Script", "Shoot"];
// The old Post-production status is still written beside the new one, so the
// flows and rollups that have not moved yet keep reading something sane.
function ppValueFor(next: HubStatus, isGraphic: boolean): string {
  if (next === "Attach Raw") return "New Shots";
  if (next === "To Design") return "To Design";
  if (next === "To Edit") return "Creatives Queue";
  if (next === "In Progress" || next === "Need Changes") return "In Progress";
  if (next === "Approve Media" || next === "Approve Post") return "To Approve";
  return "Ready to Post";
}

// Flowy never holds a To do (v3 §16.3): the moment work goes to Flowy it is
// In progress, then Edited / Designed. So only a record In progress with no
// person on it reads as Flowy's; the old "Flowy's Queue" (still To do) reads
// Unassigned.
const isFlowyName = (name: string) => /^flowy$/i.test(String(name || "").trim());
function ownerOf(f: any, status: HubStatus): Owner {
  const person = firstLink(f?.assignee);
  if (person && person.label) {
    // Always the same key, whatever member row it comes from: the board looks
    // its group up by "flowy".
    if (isFlowyName(person.label)) return { kind: "flowy", key: "flowy", name: "Flowy" };
    return { kind: "person", key: person.id || person.label, name: person.label, initials: initialsOf(person.label) };
  }
  return { kind: "none", key: "none", name: "Unassigned" };
}

function headingOf(f: any, isGraphic: boolean): string {
  const custom = stripRichText(f?.customPostName).trim();
  if (custom) return custom;
  const order = isGraphic
    ? [f?.visualHook, f?.slide1Copy, f?.hook, f?.body]
    : [f?.hook, f?.visualHook, f?.body];
  for (const v of order) {
    const t = stripRichText(v).trim();
    if (t) return t.split("\n")[0].trim();
  }
  const pn = stripRichText(f?.postName).replace(/^\s*-\s*/, "").trim();
  return pn || "Untitled";
}

// Script Files pairings are named "<kind> · <file>" by the studio. Until
// round 2 reads the table itself, the counts come from those names.
// Two buckets and nothing else: raw material, or one of the version types.
// The list is the same on a video card and a graphic card, so the words never
// change under you (Karen, 2026-09-29).
const SLIDE_CAP = 12;
const RAW_ROLE = "Raw Material";
const OVERLAY_ROLE = "Overlay Material";
const MEDIA_ROLE = "Media Version";
const THUMB_ROLE = "Thumbnail Version";
const SLOT_NAMES = ["Version A", "Version B"];
// The same two, for a tile too narrow to read them whole (Karen, 2026-10-09).
const SLOT_SHORT = ["V.A", "V.B"];
// Each kind of card offers only the types that mean anything on it: a video
// has no slides, a single graphic has no thumbnail (Karen, 2026-10-01).
// Round sixty-six: nothing is filed as a thumbnail any more. A thumbnail that
// could be uploaded on its own showed up as a second item under Media to Post,
// beside the video it belongs to, and read as two things going out
// (Karen, 2026-10-03). Files already filed that way still draw the poster.
const rolesFor = (kind: "carousel" | "graphic" | "video"): string[] => (kind === "carousel"
  ? [...Array.from({ length: SLIDE_CAP }, (_, i) => `Slide ${i + 1} Version`), RAW_ROLE, OVERLAY_ROLE]
  : [MEDIA_ROLE, RAW_ROLE, OVERLAY_ROLE]);
// What each one is stored as on the pairing. Airtable's own "Used as" list is
// fixed, so a slide and a graphic's media version share "Designed slides" and
// are told apart by the file's name.
const VERSION_USED_AS = ["Edited videos", "Designed slides", "Designed thumbnail"];
const isVersionUse = (used: string) => VERSION_USED_AS.includes(String(used || ""));
const slideInRole = (role: string) => { const m = /^Slide (\d+) Version$/.exec(String(role || "")); return m ? Number(m[1]) : 0; };
function countPairs(f: any, prefixes: string[]): number {
  return allLinks(f?.scriptFiles).filter((l) => {
    const label = l.label.toLowerCase();
    return prefixes.some((p) => label.startsWith(p.toLowerCase()));
  }).length;
}
// Raw attached, off the pairing names on the card: everything that is not one
// of the version types. The names move with the type now, so the column
// follows a file that changes what it is (Karen, 2026-09-29).
function countRaw(f: any): number {
  return allLinks(f?.scriptFiles).filter((l) => {
    const label = String(l.label || "").toLowerCase();
    return !VERSION_USED_AS.some((v) => label.startsWith(v.toLowerCase()));
  }).length;
}

function shapeCard(rec: any): Card {
  const f = rec?.fields || {};
  const isGraphic = isGraphicRecord(f);
  const status = hubStatusOf(f);
  const brand = firstLink(f.brand);
  const session = firstLink(f.filmingSession);
  const dueDate = parseDay(f.dueDate);
  const rawCount = countRaw(f);
  const versionCount = isGraphic
    ? (countPairs(f, ["Designed slides"]) > 0 ? 1 : 0)
    : countPairs(f, ["Edited videos", "Designed slides"]);
  const handed = f.productionStarted ? parseDay(f.productionStarted) : (f.lastUpdate ? new Date(f.lastUpdate) : null);
  const lu = f.lastUpdate ? new Date(f.lastUpdate).getTime() : 0;
  const owner = ownerOf(f, status);
  const notes = flowyNotesOf(f.flowyOrder);
  // Flowy is editing it when it is assigned to Flowy, or when it was sent to
  // Flowy's edit in the last twenty minutes, whoever it is assigned to: a card
  // with a person on it read To Edit and "Unassigned" while Flowy cut it
  // (Karen, 2026-10-11).
  const sentToFlowy = !!notes.sentAt && Date.now() - notes.sentAt < FLOWY_STALE_MS;
  const flowyWorking = isRunning(status) && (owner.kind === "flowy" || sentToFlowy);
  const noted = (status === "To Edit" || status === "To Design") && !!notes.failed;
  const lost = !noted && flowyWorking && !!notes.sentAt && Date.now() - notes.sentAt > FLOWY_STALE_MS;
  const flowyIssue = noted ? notes.failed : lost ? FLOWY_LOST_NOTE(isGraphic) : "";
  // A lost job is Flowy's to own, never the person's.
  const flowyIssueKind: "needs" | "failed" | "" = noted ? notes.kind : lost ? "failed" : "";
  return {
    id: String(rec.id),
    rec,
    heading: headingOf(f, isGraphic),
    format: String(selectLabel(f.format) || "").trim(),
    isGraphic,
    status,
    subformat: stripRichText(firstLink(f.subformat)?.label || "").trim(),
    rawStatus: selectLabel(f.postProductionStatus),
    owner,
    brandId: brand?.id || "",
    brandName: brand?.label || "",
    deliveryStyle: String(selectLabel(f.deliveryStyle) || "").trim(),
    created: f.createdDate ? new Date(f.createdDate).getTime() || 0 : 0,
    sessionId: session?.id || "",
    dueDate,
    dueLabel: dueLabelFor(f.dueDate),
    overdue: !!dueDate && dayDiff(new Date(), dueDate) < 0,
    comments: toNum(f.commentsCount),
    rawCount,
    pillar: stripRichText(firstLink(f.topicCategory)?.label).trim(),
    versionCount,
    handedOver: handed && !isNaN(handed.getTime()) ? handed : null,
    approvedOn: shortDate(f.approvalEnded),
    lastUpdate: isFinite(lu) ? lu : 0,
    slides: selectLabel(f.slidesCount),
    duration: formatDuration(f.duration),
    flowyWorking: flowyWorking && !flowyIssue,
    flowyIssue,
    flowyIssueKind,
    flowySentAt: notes.sentAt,
    flowyTemplate: notes.template,
    flowyLong: status === "Approve Media" ? notes.long : "",
  };
}

const needsFootage = (c: Card) => !c.isGraphic && c.rawCount === 0;

// The expanded row's first field, named per format the way the studio names a
// card's headline (cardTitleSpec): a graphic's hook is its "Cover title", a
// post-first video's Body is its "Text overlay", and every other video shows
// its "Hook on Screen". The field itself, never the custom name.
function leadFieldOf(c: Card): { label: string; value: string } {
  const f = c.rec?.fields || {};
  if (c.isGraphic) return { label: "Cover title", value: stripRichText(f.visualHook).trim() };
  if (TEXT_OVERLAY_FORMATS.includes(c.format)) return { label: "Text overlay", value: stripRichText(f.body).trim() };
  return { label: "Visual Hook", value: stripRichText(f.visualHook).trim() };
}

// Resizable table columns (px), every fixed column after Hook, in order. The
// Hook column takes whatever width is left, as in the studio's table.
const QUEUE_COLS = [132, 150, 150, 116, 148, 132]; // Status · Format · Shoot batch · Due date · Assignee · Raw attached
const APPROVE_COLS = [132, 148, 148, 134];         // Status · Format · Made by · Versions attached
const sumOf = (list: number[]) => list.reduce((a, b) => a + b, 0);

// The board's columns and the card's sides. Karen, 2026-10-08: tidier
// columns, about 4.2 across where 3.8 fitted, by trimming the side margins
// only, never the type or the buttons. Was 344px columns, 16px apart, 12px
// inside, and cards 22px in on the left and 16px on the right.
const BOARD_COL_W = 314;
const BOARD_COL_GAP = 12;
const CARD_PAD = "13px 14px 14px 16px";
const CARD_BUTTONS_PAD = "0 14px 14px 16px";
const CARD_FOOT_PAD = "7px 16px 8px";

// ─── Small visual atoms ──────────────────────────────────────────────────────
let waveSeq = 0;

// The Flowy wave: the one animated mark in the product. `size` is its width;
// the wave keeps the 34:14 proportion of the studio's WaveAvatar.
// `ink` paints the wave one flat colour instead of the cycling gradient. Only
// for the places it sits ON the gradient, where its own purples disappear.
function FlowyMark({ size = 22, glow = false, thinking = false, ink, style }: { size?: number; glow?: boolean; thinking?: boolean; ink?: string; style?: React.CSSProperties }) {
  const idRef = useRef<string>("");
  if (!idRef.current) { waveSeq += 1; idRef.current = `chWave${waveSeq}`; }
  const gid = idRef.current;
  const h = Math.round((size * 14) / 34);
  const dur = thinking ? "1.2s" : "2.6s";
  const cycle = thinking ? "1.6s" : "5s";
  return (
    <div style={{ position: "relative", width: `${size}px`, height: `${h}px`, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, ...style }}>
      {glow && (
        <div
          aria-hidden="true"
          style={{
            position: "absolute", inset: `-${Math.round(size * 0.3)}px -${Math.round(size * 0.2)}px`,
            background: thinking
              ? "radial-gradient(ellipse at center, rgba(168,85,247,0.32) 0%, rgba(236,72,153,0.12) 40%, rgba(168,85,247,0) 70%)"
              : "radial-gradient(ellipse at center, rgba(168,85,247,0.16) 0%, rgba(236,72,153,0.08) 40%, rgba(168,85,247,0) 70%)",
            borderRadius: "50%",
            animation: `chGlowPulse ${dur} ease-in-out infinite`,
            pointerEvents: "none",
          }}
        />
      )}
      <svg viewBox="0 0 31 8" fill="none" style={{ position: "relative", width: `${Math.round(size * 0.88)}px`, height: `${Math.max(4, Math.round(h * 0.64))}px`, zIndex: 2, overflow: "visible" }}>
        <defs>
          <linearGradient id={gid} x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#EC4899">
              <animate attributeName="stop-color" values="#EC4899;#A855F7;#6366F1;#A855F7;#EC4899" dur={cycle} repeatCount="indefinite" />
            </stop>
            <stop offset="50%" stopColor="#A855F7">
              <animate attributeName="stop-color" values="#A855F7;#6366F1;#EC4899;#A855F7" dur={cycle} repeatCount="indefinite" />
            </stop>
            <stop offset="100%" stopColor="#6366F1">
              <animate attributeName="stop-color" values="#6366F1;#EC4899;#A855F7;#6366F1" dur={cycle} repeatCount="indefinite" />
            </stop>
          </linearGradient>
        </defs>
        <path
          d="M2.45808 1.72226C1.74654 1.72226 0.769662 2.9375 0.750379 4.1529C0.728363 5.54055 1.66854 6.65884 2.885 6.74558C4.17988 6.83792 4.73596 5.46653 5.30425 4.1529C5.87254 2.83927 6.36311 0.75 7.15425 0.75C7.9454 0.75 9.48709 6.45133 12.2774 6.4215C14.017 6.4029 15.3507 5.03796 16.262 4.1529C17.1733 3.26784 18.2669 2.19642 19.9074 2.19642C21.5478 2.19642 22.9505 3.50473 24.0889 4.31494C25.2274 5.12515 26.2869 6.18013 27.6467 5.93537C28.2918 5.81924 29.0209 5.62496 29.75 4.1529"
          stroke={ink || `url(#${gid})`}
          strokeWidth="1.8"
          strokeLinecap="round"
          fill="none"
          style={{ animation: `chWaveShimmer ${dur} ease-in-out infinite` }}
        />
      </svg>
    </div>
  );
}

function Avatar({ owner, size = 20, picture }: { owner: Owner; size?: number; picture?: any }) {
  const none = owner.kind === "none";
  const font = Math.max(8, Math.round(size * 0.475));
  const url = owner.kind === "person"
    ? (attachmentOf(picture)?.thumbnails?.small?.url || attachmentOf(picture)?.url || "")
    : "";
  if (url) {
    return (
      <img loading="lazy" decoding="async" src={url} alt="" aria-hidden="true"
        style={{ width: `${size}px`, height: `${size}px`, borderRadius: "50%", flexShrink: 0, objectFit: "cover", display: "block" }} />
    );
  }
  return (
    <span
      aria-hidden="true"
      style={{
        width: `${size}px`, height: `${size}px`, borderRadius: "50%", flexShrink: 0,
        display: "inline-flex", alignItems: "center", justifyContent: "center",
        background: none ? "#F1F5F9" : "#F3E8FF", color: none ? "#94A3B8" : ACCENT_DEEP,
        fontFamily: MONO, fontSize: `${font}px`, fontWeight: 600, letterSpacing: "0.02em",
      }}
    >
      {owner.kind === "person" ? owner.initials : "?"}
    </span>
  );
}

// Weight 500 everywhere; a card's tag is also 1px smaller than a table's
// (Karen, 2026-09-14).
function StatusPill({ label, compact = false }: { label: string; compact?: boolean }) {
  const t = STATUS_TONES[label] || STATUS_TONES["To Edit"];
  return (
    <span
      style={{
        display: "inline-flex", alignItems: "center", gap: "6px", padding: "4px 9px", borderRadius: "999px",
        background: t.bg, color: t.text, fontFamily: MONO, fontSize: compact ? "9.5px" : "10.5px", fontWeight: 500,
        letterSpacing: "0.04em", textTransform: "uppercase", whiteSpace: "nowrap", lineHeight: 1.2,
      }}
    >
      <span aria-hidden="true" style={{ width: "6px", height: "6px", borderRadius: "50%", background: t.dot, flexShrink: 0 }} />
      {label}
    </span>
  );
}

// What a Flowy job that went wrong shows, the Scheduling Board's two marks:
// yellow "Needs you" when the person has something to fix, the colour of
// "your turn", and red "Failed" when Flowy tried twice and could not, for an
// edit and a design alike. Neither is a status: it sits on the card's stage
// and goes the moment Try again is pressed (Karen, 2026-10-08).
const NEEDS_TONE = { bg: "#FEF9C3", text: "#854D0E", dot: "#CA8A04", border: "#FDE68A" };
const FAILED_TONE = { bg: "#FEF2F2", text: "#B91C1C", dot: "#DC2626", border: "#FECACA" };
const FLOWY_FAILED_LABEL = "Failed";
const issueTone = (kind: string) => (kind === "needs" ? NEEDS_TONE : FAILED_TONE);
const issueLabel = (kind: string) => (kind === "needs" ? "Needs you" : FLOWY_FAILED_LABEL);
function FlowyIssuePill({ kind, compact = false, title }: { kind: string; compact?: boolean; title?: string }) {
  const t = issueTone(kind);
  return (
    <span title={title} style={{ display: "inline-flex", alignItems: "center", gap: "6px", padding: "4px 9px", borderRadius: "999px", background: t.bg, color: t.text, fontFamily: MONO, fontSize: compact ? "9.5px" : "10.5px", fontWeight: 500, letterSpacing: "0.04em", textTransform: "uppercase", whiteSpace: "nowrap", lineHeight: 1.2, flexShrink: 0 }}>
      <span aria-hidden="true" style={{ width: "6px", height: "6px", borderRadius: "50%", background: t.dot, flexShrink: 0 }} />
      {issueLabel(kind)}
    </span>
  );
}

function Checkbox({
  checked, indeterminate = false, locked = false, title, onChange,
}: { checked: boolean; indeterminate?: boolean; locked?: boolean; title?: string; onChange?: () => void }) {
  const on = checked || indeterminate;
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={indeterminate ? "mixed" : checked}
      aria-label={title || (checked ? "Deselect record" : "Select record")}
      title={title || (locked ? BUSY_NOTE : "Select record")}
      disabled={locked}
      onClick={(e) => { e.stopPropagation(); if (!locked && onChange) onChange(); }}
      style={{
        width: "18px", height: "18px", borderRadius: "5px", flexShrink: 0, padding: 0,
        display: "inline-flex", alignItems: "center", justifyContent: "center",
        background: on ? ACCENT : (locked ? "#F4F4F5" : "white"),
        border: `1px solid ${on ? ACCENT : (locked ? "#E4E6EB" : "#D4D4D4")}`,
        cursor: locked ? "not-allowed" : "pointer",
        transition: "background 0.15s ease, border-color 0.15s ease",
      }}
    >
      {indeterminate ? <Minus size={11} strokeWidth={3} color="white" /> : (checked ? <Check size={11} strokeWidth={3} color="white" /> : null)}
    </button>
  );
}

function MonoLabel({ children, color = INK_MUTED, size = 11, weight = 600, tracking = "0.08em", style }: {
  children: React.ReactNode; color?: string; size?: number; weight?: number; tracking?: string; style?: React.CSSProperties;
}) {
  return (
    <span style={{ fontFamily: MONO, fontSize: `${size}px`, fontWeight: weight, letterSpacing: tracking, textTransform: "uppercase", color, ...style }}>
      {children}
    </span>
  );
}

// Every popover sits over a full-screen transparent catcher one layer below it.
function ClickCatcher({ onClose, z = 55 }: { onClose: () => void; z?: number }) {
  return <div aria-hidden="true" onMouseDown={onClose} style={{ position: "fixed", inset: 0, zIndex: z, background: "transparent" }} />;
}

// ─── Handing a card to someone ───────────────────────────────────────────────
// One sheet for every "assign" there is: the board's row menu, a whole
// selection at once, and the button inside a record. It is a proper window
// rather than a list inside a menu, because picking a person means reading
// names, hunting for one, and sometimes inviting somebody who is not there
// yet — none of which fits a 268px strip (Karen, 2026-09-29).
// On a record-only page there is no board behind, so a card that cannot be
// found would leave the screen blank with nothing to read or do. This says
// which of the two it is: still looking, or not on this board.
function EmbedWaiting({ done }: { done: boolean }) {
  const say = () => { try { window.parent.postMessage({ type: "flowshift:close" }, "*"); } catch { /* not framed */ } };
  return (
    <div style={{ position: "fixed", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", padding: "20px" }}>
      <div style={{ maxWidth: "320px", padding: "22px 24px", background: "#fff", borderRadius: "14px", boxShadow: "0 18px 50px -20px rgba(16,18,24,.45)", textAlign: "center", fontFamily: GEIST }}>
        <div style={{ fontSize: "14px", fontWeight: 500, color: INK }}>
          {done ? "This one is not on this board." : "Opening the card"}
        </div>
        <div style={{ marginTop: "6px", fontSize: "12.5px", lineHeight: 1.5, color: "#6C707A" }}>
          {done
            ? "It may have moved on, or been deleted."
            : "Finding it among the board's cards."}
        </div>
        {done && (
          <div role="button" onClick={say} style={{ marginTop: "16px", height: "34px", display: "inline-flex", alignItems: "center", padding: "0 16px", borderRadius: "9px", border: "1px solid #E8EAEE", fontSize: "13px", fontWeight: 500, color: INK, cursor: "pointer" }}>
            Close
          </div>
        )}
      </div>
    </div>
  );
}

function AssignSheet({ title, people, currentId, busy, onPick, onInvite, onClose, top = null }: {
  title: string;
  top?: React.ReactNode;
  people: { id: string; displayName: string; email: string; role: string; invited?: boolean; profilePicture?: any }[] | null;
  currentId: string;
  busy?: boolean;
  onPick: (m: any | null) => void;
  onInvite: null | ((o: { email: string; name: string; role: string }) => Promise<any>);
  onClose: () => void;
}) {
  const [term, setTerm] = useState("");
  const [inviting, setInviting] = useState(false);
  const [draft, setDraft] = useState({ email: "", name: "", role: "Brand Collaborator" });
  const [sending, setSending] = useState(false);
  const list = (people || []).filter((m) => !/^flowy$/i.test(String(m.displayName || "").trim())).filter((m) => {
    const t = term.trim().toLowerCase();
    if (!t) return true;
    return `${m.displayName} ${m.email} ${m.role}`.toLowerCase().includes(t);
  });
  const send = async () => {
    if (!onInvite || !draft.email.trim() || sending) return;
    setSending(true);
    const made = await onInvite({ ...draft });
    setSending(false);
    if (made) { setInviting(false); onPick(made); }
  };
  const avatar = (name: string, pic: any) => {
    const url = attachmentOf(pic)?.thumbnails?.small?.url || attachmentOf(pic)?.url || "";
    return url
      ? <img loading="lazy" decoding="async" src={url} alt="" style={{ width: "30px", height: "30px", borderRadius: "50%", objectFit: "cover", flexShrink: 0 }} />
      : <span aria-hidden="true" style={{ width: "30px", height: "30px", borderRadius: "50%", background: "#F3E8FF", color: ACCENT_DEEP, display: "inline-flex", alignItems: "center", justifyContent: "center", fontFamily: MONO, fontSize: "10.5px", fontWeight: 600, flexShrink: 0 }}>{initialsOf(name)}</span>;
  };
  const row = (key: string, lead: React.ReactNode, name: string, under: string, on: boolean, onGo: () => void) => (
    <button key={key} type="button" role="option" aria-selected={on} aria-label={name} className="ch-menu-row" disabled={!!busy} onClick={onGo}
      style={{ display: "flex", alignItems: "center", gap: "11px", width: "100%", textAlign: "left", padding: "8px 10px", borderRadius: "9px", border: "none", background: on ? WASH : "transparent", cursor: busy ? "wait" : "pointer" }}>
      {lead}
      <span style={{ flex: 1, minWidth: 0 }}>
        <span style={{ display: "block", fontFamily: GEIST, fontSize: "13.5px", fontWeight: on ? 500 : 400, color: on ? ACCENT_DEEP : INK, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{name}</span>
        {!!under && <span style={{ display: "block", marginTop: "1px", fontFamily: GEIST, fontSize: "11.5px", fontWeight: 400, color: INK_MUTED, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{under}</span>}
      </span>
      {on && <Check size={14} strokeWidth={2.4} style={{ flexShrink: 0, color: ACCENT_DEEP }} />}
    </button>
  );
  return createPortal(
    <div style={{ position: "fixed", inset: 0, zIndex: 10080, display: "flex", alignItems: "center", justifyContent: "center", padding: "24px", background: "rgba(23,23,23,0.38)" }}
      onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}
      onKeyDown={(e) => { if (e.key === "Escape") { e.stopPropagation(); onClose(); } }}>
      <div role="dialog" aria-modal="true" aria-label="Assign to a Creative"
        style={{ width: "min(420px, 94vw)", maxHeight: "min(560px, 86vh)", display: "flex", flexDirection: "column", background: "white", borderRadius: "16px", boxShadow: SHADOW_POP, overflow: "hidden" }}>
        <div style={{ flexShrink: 0, padding: "18px 20px 12px", borderBottom: `1px solid ${HAIR_SOFT}` }}>
          <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
            {inviting && (
              <button type="button" title="Back to the list" aria-label="Back to the list" onClick={() => setInviting(false)}
                style={{ width: "24px", height: "24px", borderRadius: "7px", border: "none", background: "transparent", color: INK_MUTED, cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", padding: 0, flexShrink: 0 }}>
                <ArrowLeft size={14} strokeWidth={2} />
              </button>
            )}
            <span style={{ flex: 1, minWidth: 0, fontFamily: GEIST, fontSize: "16px", fontWeight: 600, color: INK, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
              {inviting ? "Invite someone" : "Who is working on this?"}
            </span>
            <button type="button" title="Close" aria-label="Close" onClick={onClose}
              style={{ width: "26px", height: "26px", borderRadius: "7px", border: "none", background: "transparent", color: INK_MUTED, cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center", padding: 0, flexShrink: 0 }}>
              <X size={15} strokeWidth={2} />
            </button>
          </div>
          <div style={{ marginTop: "4px", fontFamily: GEIST, fontSize: "12.5px", fontWeight: 400, color: INK_MUTED, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{title}</div>
          {!inviting && (people || []).length > 5 && (
            <input autoFocus value={term} placeholder="Search by name or email" aria-label="Search the people"
              onChange={(e) => setTerm(e.target.value)}
              style={{ width: "100%", boxSizing: "border-box", height: "34px", marginTop: "12px", padding: "0 11px", borderRadius: "9px", border: `1px solid ${HAIR}`, outline: "none", fontFamily: GEIST, fontSize: "13px", color: INK }} />
          )}
        </div>
        {/* Post as, on a card's own Assign (Karen, 2026-10-18). */}
        {!!top && !inviting && <div style={{ flexShrink: 0, padding: "14px 20px", borderBottom: `1px solid ${HAIR_SOFT}` }}>{top}</div>}
        {inviting ? (
          <div style={{ padding: "16px 20px 18px" }}>
            <input autoFocus type="email" value={draft.email} placeholder="Their email" aria-label="Their email"
              onChange={(e) => setDraft((d) => ({ ...d, email: e.target.value }))}
              onKeyDown={(e) => { if (e.key === "Enter") send(); }}
              style={{ width: "100%", boxSizing: "border-box", height: "36px", padding: "0 11px", marginBottom: "8px", borderRadius: "9px", border: `1px solid ${HAIR}`, outline: "none", fontFamily: GEIST, fontSize: "13px", color: INK }} />
            <input value={draft.name} placeholder="Their name (optional)" aria-label="Their name"
              onChange={(e) => setDraft((d) => ({ ...d, name: e.target.value }))}
              onKeyDown={(e) => { if (e.key === "Enter") send(); }}
              style={{ width: "100%", boxSizing: "border-box", height: "36px", padding: "0 11px", marginBottom: "12px", borderRadius: "9px", border: `1px solid ${HAIR}`, outline: "none", fontFamily: GEIST, fontSize: "13px", color: INK }} />
            <MonoLabel color={INK_MUTED} size={9.5} weight={600} tracking="0.08em" style={{ display: "block", marginBottom: "7px" }}>What they can do</MonoLabel>
            <div style={{ display: "flex", flexWrap: "wrap", gap: "6px", marginBottom: "16px" }}>
              {INVITE_ROLES.map((r) => (
                <button key={r} type="button" aria-pressed={draft.role === r} onClick={() => setDraft((d) => ({ ...d, role: r }))}
                  style={{ height: "26px", padding: "0 11px", borderRadius: "999px", cursor: "pointer", whiteSpace: "nowrap", background: draft.role === r ? WASH : "white", border: `1px solid ${draft.role === r ? "rgba(168,85,247,0.45)" : HAIR}`, color: draft.role === r ? ACCENT_DEEP : INK_2, fontFamily: GEIST, fontSize: "12px", fontWeight: 500 }}>
                  {r.replace("Brand ", "")}
                </button>
              ))}
            </div>
            <button type="button" className={draft.email.trim() && !sending ? "ch-gcta" : undefined} disabled={!draft.email.trim() || sending} onClick={send}
              style={{ width: "100%", height: "36px", borderRadius: "9px", border: "none", background: GRADIENT, color: "white", fontFamily: GEIST, fontSize: "13px", fontWeight: 500, cursor: draft.email.trim() && !sending ? "pointer" : "not-allowed", opacity: draft.email.trim() && !sending ? 1 : 0.45 }}>
              {sending ? "Sending\u2026" : "Send the invitation and hand it over"}
            </button>
          </div>
        ) : (
          <>
            <div role="listbox" aria-label="The people on this brand" className="ch-thinscroll" style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: "8px 12px" }}>
              {people === null
                ? <div style={{ padding: "14px 10px", fontFamily: GEIST, fontSize: "13px", color: INK_3 }}>Loading people\u2026</div>
                : (
                  <>
                    {row("none", <span aria-hidden="true" style={{ width: "30px", height: "30px", borderRadius: "50%", border: `1px dashed ${HAIR}`, display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0, color: INK_MUTED }}><Users size={13} strokeWidth={2} /></span>,
                      "Nobody", "Leave it unassigned", !currentId, () => onPick(null))}
                    {list.length === 0 && (
                      <div style={{ padding: "14px 10px", fontFamily: GEIST, fontSize: "13px", color: INK_3 }}>
                        {term.trim() ? "Nobody by that name." : "Nobody else on this brand yet."}
                      </div>
                    )}
                    {list.map((m) => row(m.id, avatar(m.displayName, m.profilePicture),
                      m.displayName || m.email || "Member",
                      [m.role, m.invited ? "invited, not in yet" : ""].filter(Boolean).join(" \u00b7 "),
                      currentId === m.id, () => onPick(m)))}
                  </>
                )}
            </div>
            {!!onInvite && (
              <div style={{ flexShrink: 0, borderTop: `1px solid ${HAIR_SOFT}`, padding: "10px 12px" }}>
                <button type="button" className="ch-menu-row" onClick={() => { setDraft({ email: term.includes("@") ? term.trim() : "", name: "", role: "Brand Collaborator" }); setInviting(true); }}
                  style={{ display: "flex", alignItems: "center", gap: "9px", width: "100%", textAlign: "left", padding: "8px 10px", borderRadius: "9px", border: "none", background: "transparent", color: ACCENT, fontFamily: GEIST, fontSize: "13.5px", fontWeight: 500, cursor: "pointer" }}>
                  <Plus size={15} strokeWidth={2.2} /> Invite someone new
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>,
    document.body,
  );
}

type MenuItem = {
  label: string;
  icon: any;
  tone?: "accent" | "danger" | "success";
  disabled?: boolean;
  title?: string;
  // An item that needs one more answer keeps the menu open and swaps its
  // contents for that question (who, when, which shoot).
  keepOpen?: boolean;
  // The last rows of the menu, fenced off under a rule: the ones you would
  // not want to hit by accident (Karen, 2026-09-28).
  zone?: "danger";
  // The event comes through so an item that opens a menu of its own can
  // anchor it under the row that was pressed.
  onClick: (e?: any) => void;
};

function MenuRows({ items, onDone }: { items: MenuItem[]; onDone: () => void }) {
  return (
    <>
      {items.map((it, i) => {
        const Icon = it.icon;
        const opensZone = it.zone === "danger" && items[i - 1]?.zone !== "danger";
        const iconColor = it.disabled ? INK_MUTED
          : it.tone === "accent" ? ACCENT
          : it.tone === "danger" ? "#DC2626"
          : it.tone === "success" ? DONE_GREEN
          : INK_ICON;
        const labelColor = it.disabled ? INK_MUTED : it.tone === "danger" ? "#DC2626" : INK;
        return (
          <React.Fragment key={it.label}>
          {opensZone && (
            <span aria-hidden="true" style={{ display: "block", margin: "6px 2px", borderTop: `1px solid ${HAIR}` }} />
          )}
          <button
            type="button"
            className={it.disabled ? "" : "ch-menu-row"}
            title={it.title}
            aria-disabled={it.disabled ? "true" : undefined}
            onClick={(e) => {
              e.stopPropagation();
              if (it.disabled) return;
              it.onClick(e);
              if (it.keepOpen) return;
              onDone();
            }}
            style={{
              display: "flex", alignItems: "center", gap: "10px", width: "100%", textAlign: "left",
              padding: "10px 12px", borderRadius: "6px", border: "none", background: "transparent",
              fontFamily: GEIST, fontSize: "14px", fontWeight: 400, color: labelColor,
              cursor: it.disabled ? "not-allowed" : "pointer", opacity: it.disabled ? 0.55 : 1,
            }}
          >
            <Icon size={15} color={iconColor} style={{ flexShrink: 0 }} />
            <span style={{ flex: 1, minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{it.label}</span>
          </button>
          </React.Fragment>
        );
      })}
    </>
  );
}

// ─── Board logic ─────────────────────────────────────────────────────────────
// One board for scripting and producing (Karen, 2026-10-22): Script, Film and
// Attach before Edit and Design, Ready after Approve. The four new tabs show
// every card for now; their own statuses are wired in a later round.
type Tab = "all" | "script" | "film" | "attach" | "edit" | "design" | "approve" | "ready";
// All comes first and is where the board opens: the whole pipeline in one
// place (Karen, 2026-10-23).
const BOARD_TABS: Tab[] = ["all", "script", "film", "attach", "design", "edit", "approve", "ready"];
// Which statuses each tab holds (Karen, 2026-10-23): Review Script sits in
// Script, In Progress and Need Changes go to Design or Edit by the card's
// kind, and Ready holds everything from To Schedule on.
const TAB_STAGES: Record<Tab, string[]> = {
  all: [...HUB_STATUSES],
  script: ["Script", "Review Script"],
  film: ["Shoot"],
  attach: ["Attach Raw"],
  design: ["To Design", "In Progress", "Need Changes"],
  edit: ["To Edit", "In Progress", "Need Changes"],
  approve: ["Approve Media", "Approve Post"],
  ready: ["To Schedule", "Scheduled", "Published", "Publish Failed"],
};
// The next-stage columns a tab shows after its own, so a card can always be
// moved forward from the board even while the tab is filtered to its own work
// (Karen, 2026-10-24). Dropping a card on one of these moves it on; it then
// lives on that stage's own tab.
const FORWARD_COLS: Partial<Record<Tab, string[]>> = {
  script: ["Shoot"],
  film: ["Attach Raw", "To Design", "To Edit"],
  attach: ["To Design", "To Edit"],
  design: ["Approve Media"],
  edit: ["Approve Media"],
  approve: ["To Schedule"],
};
// The tab a card belongs on, by its status and, for Design and Edit, its kind.
const tabOfCard = (c: { status: string; isGraphic: boolean }): Tab => {
  if (TAB_STAGES.design.includes(c.status) && TAB_STAGES.edit.includes(c.status)) return c.isGraphic ? "design" : "edit";
  if (c.status === "To Design") return "design";
  if (c.status === "To Edit") return "edit";
  return (BOARD_TABS.find((t) => t !== "all" && TAB_STAGES[t].includes(c.status)) || (c.isGraphic ? "design" : "edit"));
};
type GroupBy = "assignee" | "status" | "batch" | "none";
// The board of columns is what the studio opens on: it is the one view that
// says where everything is at a glance (Karen, 2026-10-02).
type View = "board" | "table" | "cards" | "calendar";
type Panel = "group" | "brand" | "workspace" | "filters" | "create" | "more" | "bulk" | null;

// Karen's seven, in her order: brand, status, assignee, due date, content
// pillar, content type, format (2026-10-12). Handed over and shoot batch came
// out; say the word and they come back.
type Filters = { brand: string; due: "any" | "overdue" | "week" | "none"; pillar: string; kind: "all" | "video" | "graphic"; format: string; assignee: string; stages: string[] };
// The board loads everything and starts on the studio's own work. Open the
// filter and any stage is there to look at (Karen, 2026-09-28).
const DEFAULT_FILTERS: Filters = { brand: "all", due: "any", pillar: "all", kind: "all", format: "all", assignee: "all", stages: STUDIO_FILTER };
const DUE_OPTIONS: { value: Filters["due"]; label: string }[] = [
  { value: "any", label: "Any deadline" }, { value: "overdue", label: "Overdue" }, { value: "week", label: "Due this week" }, { value: "none", label: "No deadline" },
];
const KIND_OPTIONS: { value: Filters["kind"]; label: string }[] = [
  { value: "all", label: "Everything" }, { value: "video", label: "Video" }, { value: "graphic", label: "Graphic" },
];

type Session = {
  id: string; label: string; start: Date | null; day: string; time: string;
  // The shoot calendar (2026-10-23). contentIds are the scripts booked into
  // this day; the capacity numbers come from Airtable (none of them read the
  // retired Shooting status — filmed is counted in the block).
  lengthMin: number; location: string; notes: string; createdAt: number;
  contentIds: string[]; bookedMin: number; freeMin: number; fillPct: number; scriptsCount: number;
  // The session's own status, user-controlled (Unplanned / Planned / In
  // progress / Ready for Production / Completed / Cancelled).
  statusLabel: string;
};
// A session's status, in the order a day moves through. The user sets it by
// hand — nothing here syncs it to the scripts (Karen, 2026-10-23: give the
// user control, one status, no backend logic).
const SESSION_STATUSES = ["Unplanned", "Planned", "In progress", "Ready for Production", "Completed", "Cancelled"] as const;
type SessionStage = "toShoot" | "ready" | "done";
// The three groups the calendar colours by: still to film, filmed and ready to
// send on, and done (everything after, plus a cancelled day).
const sessionStageOf = (s: Session): SessionStage =>
  s.statusLabel === "Completed" || s.statusLabel === "Cancelled" ? "done"
    : s.statusLabel === "Ready for Production" ? "ready"
      : "toShoot";
// A day with no date is one the user has not placed on the calendar yet.
const isUndatedSession = (s: Session) => !s.start;
// Filmed, worked out in the block instead of the retired Airtable rollup: a
// booked script counts as filmed once its one status has moved past Shoot.
const BEFORE_SHOT: string[] = ["Script", "Review Script", "Shoot"];
const sessionFilmedCount = (s: Session, cardById: Map<string, Card>): number =>
  s.contentIds.reduce((n, id) => {
    const c = cardById.get(id);
    return c && !BEFORE_SHOT.includes(c.status) ? n + 1 : n;
  }, 0);
// The scripts booked into a day. Either side counts — the card may name the
// session or the session may list the card — and the just-booked / unbooked
// maps hold a change made this moment, before the read agrees (ported from the
// Scripting Studio's scriptsInSession). Nothing is dropped for want of footage.
function scriptsInSession(
  s: Session, pool: Card[],
  justBooked?: Record<string, string>, unbooked?: Record<string, string>,
): Card[] {
  const ids = new Set(s.contentIds);
  return pool.filter((c) => {
    if (unbooked?.[c.id] === s.id) return false;
    return ids.has(c.id) || c.sessionId === s.id || justBooked?.[c.id] === s.id;
  });
}
// The calendar tag's colour, by the day's own status. Red still to shoot,
// yellow ready to send on, green done.
const CAL_TONE: Record<SessionStage, string> = { toShoot: "#FF5A5F", ready: "#C9A93D", done: "#16A34A" };
// The capacity ramp — one source for the bar and its label.
function capacityColor(pct: number): string {
  if (pct >= 85) return "#E5484D";
  if (pct >= 60) return "#C9A93D";
  return "#16A34A";
}
// "2 hr" · "1 hr 30 min" · "45 min".
function formatSessionLength(min: number): string {
  const h = Math.floor(min / 60);
  const m = Math.round(min % 60);
  if (h && m) return `${h} hr ${m} min`;
  if (h) return `${h} hr`;
  return `${m} min`;
}
// ── Calendar geometry (ported verbatim from the Scripting Studio) ───────────
// The whole day canvas is derived from ONE constant — HOUR_H. 6 AM–6 PM at
// 64px/hour = 768px, an hour hairline every 64px, so nothing is eyeballed.
const CAL_HOUR_H = 64;
const CAL_START_HOUR = 6;
const CAL_END_HOUR = 18;
const CAL_GUTTER_W = 64;
const CAL_CANVAS_H = (CAL_END_HOUR - CAL_START_HOUR) * CAL_HOUR_H;
const CAL_PX_PER_MIN = CAL_HOUR_H / 60;
const CAL_HOUR_TICKS = Array.from({ length: CAL_END_HOUR - CAL_START_HOUR - 1 }, (_, i) => CAL_START_HOUR + 1 + i);
const calHourTop = (h: number) => (h - CAL_START_HOUR) * CAL_HOUR_H;
const calHourLabel = (h: number) => `${h % 12 === 0 ? 12 : h % 12} ${h >= 12 ? "PM" : "AM"}`;
// Monday-first start of the week containing `d`.
function startOfWeek(d: Date): Date {
  const x = new Date(d);
  x.setHours(0, 0, 0, 0);
  x.setDate(x.getDate() - ((x.getDay() + 6) % 7));
  return x;
}
const sameDay = (a: Date, b: Date) => a.toDateString() === b.toDateString();
// One positioned block per dated session. Clashing blocks share the width
// Google-Calendar style: each takes the first free column.
type CalBlock = { session: Session; startMin: number; endMin: number; top: number; height: number; scripts: number; col: number; cols: number };
function calBlocksForDay(daySessions: Session[], scriptsOf: (s: Session) => number): CalBlock[] {
  const blocks = daySessions
    .map((s): CalBlock | null => {
      const st = s.start;
      if (!st || isNaN(st.getTime())) return null;
      const mins = st.getHours() * 60 + st.getMinutes();
      const len = Math.max(30, s.lengthMin || 60);
      const top = Math.max(0, (mins - CAL_START_HOUR * 60) * CAL_PX_PER_MIN);
      return { session: s, startMin: mins, endMin: mins + len, top, height: Math.max(46, len * CAL_PX_PER_MIN), scripts: scriptsOf(s), col: 0, cols: 1 };
    })
    .filter(Boolean)
    .sort((a, b) => (a as CalBlock).startMin - (b as CalBlock).startMin) as CalBlock[];
  let cluster: CalBlock[] = [];
  let clusterEnd = -1;
  const closeCluster = () => {
    const width = cluster.reduce((n, b) => Math.max(n, b.col + 1), 1);
    cluster.forEach((b) => { b.cols = width; });
    cluster = [];
    clusterEnd = -1;
  };
  for (const b of blocks) {
    if (cluster.length && b.startMin >= clusterEnd) closeCluster();
    const taken = new Set(cluster.filter((c) => c.endMin > b.startMin).map((c) => c.col));
    let col = 0;
    while (taken.has(col)) col += 1;
    b.col = col;
    cluster.push(b);
    clusterEnd = Math.max(clusterEnd, b.endMin);
  }
  if (cluster.length) closeCluster();
  return blocks;
}

const TAB_LABEL: Record<Tab, string> = { all: "All", script: "Script", film: "Shoot", attach: "Attach", edit: "Edit", design: "Design", approve: "Approve", ready: "Ready" };
const GROUP_VALUE_LABEL: Record<GroupBy, string> = { assignee: "Assignee", status: "Status", batch: "Shoot batch", none: "Nothing" };

// A card's status pill on the queue tabs says what happened to it; on the
// Approve tab it says what the owner has to decide.
function pillLabel(c: Card, _tab: Tab): string {
  // One word for one state: the pill says exactly what the field says, on
  // every tab (Karen, 2026-09-28).
  void _tab;
  return c.status;
}

// The columns a tab always shows, in Karen's order (2026-10-02). The board
// draws every one of them whether or not it holds anything: an empty column is
// how you see there is nothing waiting at that stage.
function statusOrder(tab: Tab): string[] {
  // The tab's own stages, then its forward stages as empty drop-targets, with
  // any duplicate dropped so a stage never shows twice.
  const fwd = FORWARD_COLS[tab] || [];
  return Array.from(new Set([...TAB_STAGES[tab], ...fwd]));
}

function withinDue(c: Card, due: Filters["due"]): boolean {
  if (due === "any") return true;
  if (due === "none") return !c.dueDate;
  if (!c.dueDate) return false;
  if (due === "overdue") return c.overdue;
  return dayDiff(new Date(), c.dueDate) <= 7 && !c.overdue;
}

// `accent` is the group's dot colour; its count chip takes a tint of it, the
// way the studio's section headers do. Assignee groups have none (neutral).
type Group = { key: string; label: string; time?: string; lead: React.ReactNode; accent?: string; rows: Card[]; progress?: { done: number; total: number } };

// The studio's colour mixers (scripting-studio-v1.tsx): tint toward white,
// shade toward black. Used for the group count chips.
function tintOf(hex: string, amount: number): string {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.split("").map((c) => c + c).join("") : h, 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const mix = (c: number) => Math.round(c + (255 - c) * amount);
  return `rgb(${mix(r)}, ${mix(g)}, ${mix(b)})`;
}
// A column's wash: the stage's own colour taken almost all the way to white,
// then a third of the way back towards the board's own grey. Pale enough that
// six of them side by side read as six stages, not six warnings
// (Karen, 2026-10-02).
function washOf(hex: string): string {
  const pale = (tintOf(hex, 0.92).match(/\d+/g) || ["244", "244", "245"]).map(Number);
  const grey = [244, 244, 245];
  const mix = pale.map((c, i) => Math.round(c * 0.66 + grey[i] * 0.34));
  return `rgb(${mix[0]}, ${mix[1]}, ${mix[2]})`;
}
function shadeOf(hex: string, amount: number): string {
  const h = hex.replace("#", "");
  const n = parseInt(h.length === 3 ? h.split("").map((c) => c + c).join("") : h, 16);
  const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
  const mix = (c: number) => Math.round(c * (1 - amount));
  return `rgb(${mix(r)}, ${mix(g)}, ${mix(b)})`;
}

